quests[39644] = { id = 39644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Enchanting Research G/3/3/3" }
quests[39645] = { id = 39645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalibrierungsexperten", description = "Es wird die Mitarbeit einiger hoch qualifizierter Experten brauchen, um diese Büretten zu kalibrieren.\n\nMyshalla Flussbrise in Feralas hat schon häufig ihre Leidenschaft für Details unter Beweis gestellt.\n\nEisenschmiede kann ich zwar nicht ausstehen, aber Krimpel Augenmaß ist für seine akkurate Arbeit weithin bekannt.\n\nUnd in der Beutebucht muss man zwar seine Geldbörse mit einem Schloss versehen, aber Tryks Gießklar war immer aufrichtig und ehrlich zu mir.", sourceObjective = "Bringt die unkalibrierten Mallorybüretten zum Kalibrieren zu den ausgewiesenen Alchemieexperten.", completion = "Ja, diese Büretten scheinen korrekt kalibriert zu sein.\n\nIch wusste, dass die drei Kollegen makellose Arbeit abliefern würden. Man sollte nie jemanden unterschätzen, der großen Wert auf winzige Details legt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[39646] = { id = 39646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Albino Elderhorn" }
quests[39647] = { id = 39647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer auf die Kleinen!" }
quests[39648] = { id = 39648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind die Kinder?", description = "Die Kinder sind verschwunden!\n\nDieser furchtbare Grumpus hat auf seinem Weg durch Draenor überall Kinder entführt. Ihr müsst sie retten!\n\nUnsere Späher haben ihn im Frostfeuergrat gesichtet.", sourceObjective = "Rettet 6 entführte Kinder.", completion = "Danke für all Eure Hilfe! Ihre Familien werden überglücklich sein, sie zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39649] = { id = 39649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grumplingbedrohung", description = "Die Grumplinge sind grauenvolle Kreaturen. Sie erledigen die Drecksarbeit für Grumpus.\n\nWenn Ihr diese Bedrohung aus dem Weg schaffen könnt, wird die Rettung der Kinder sicher ein Spaziergang.", sourceObjective = "Tötet 8 Grumplinge.", completion = "Na das ging schnell! Ohne seine Diener wird Grumpus ganz schön schwitzen müssen, um seine Arbeit zu beenden.\n\nNehmt die hier. Ich habe sie speziell für Euch anfertigen lassen.\n\nMan weiß ja nie, worauf man hier draußen in Draenor stößt!", sourceObjectiveStatus = "unverified-source-field" }
quests[39651] = { id = 39651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grumpus", description = "Die Legende von Grumpus ist eine von Draenors ältesten Geschichten.\n\nSie handelt von einem gemeinen Wüstling, der in einer kalten Windernacht kommt und ungezogene Kinder holt. In seinem Unterschlupf beschenkt er sie dann mit schrecklichem Spielzeug und erschafft seine Diener aus ihren Tränen.\n\nDoch Grumpus ist keine Legende, es gibt ihn wirklich und hat unsere Kinder entführt! Bitte, Ihr müsst ihm ein Ende setzen!", sourceObjective = "Tötet Grumpus.", completion = "Danke, {name}. Ohne Euch hätte ich das nicht geschafft.\n\nBitte, nehmt das als Zeichen meiner Dankbarkeit.\n\nFrohes Fest!", sourceObjectiveStatus = "unverified-source-field" }
quests[39652] = { id = 39652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenherrschaft", description = "Dank Eurer Hilfe konnte Thrymjaris aus den Klauen dieses grässlichen Dämons entkommen. Sie bat mich, auf Euch zu warten und Euch zu ihr zu bringen, wenn Ihr Eure Feinde ausgelöscht habt.\n\nSie hat unsere Brut am Gipfel des Thorimshorns versammelt und plant einen Gegenangriff.\n\nWürdet Ihr uns dabei unterstützen?", sourceObjective = "Sprecht mit Vethir, um zum Gipfel des Thorimshorns zu fliegen.", completion = "Für meine Brut seid Ihr wahrlich ein Held.\n\nAb heute habt Ihr mächtige neue Verbündete, Fremder. Der Gottkönig tut gut daran, Euch zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39654] = { id = 39654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odyn und die Valarjar", description = "Habt keine Angst, <Sterblicher/Sterbliche>, Ihr seid nicht tot. Odyn selbst hat mir aufgetragen, Euch vor Eurem Ableben einzusammeln.\n\nIch werde Euch jetzt zu ihm bringen. Bitte folgt mir.", sourceObjective = "Lasst Euch von Danica zu Odyn bringen.", completion = "Jetzt kennen Euch alle hier. Es wird Zeit, dass mein Champion mit angemessenen Waffen ausgestattet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[39655] = { id = 39655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähne zusammenbeißen und noch mal versuchen!", description = "Das U-Boot hatte offensichtlich mehr Feuerkraft, als wir dachten! Sie haben einen Erstschlag gegen uns geführt, bevor wir überhaupt reagieren konnten.\n\nDer Verlust von Schiffen gehört bei Seeschlachten dazu, Kommandant. Zum Glück sind wir auf genau solch eine Situation vorbereitet. Sprecht mit Yanas unten an den Trockendocks. Er dürfte uns helfen können, schnell einen neuen Zerstörer zu produzieren. Kommt zurück, wenn das Schiff bereit ist, und wir werden eine neue Mission für Euch haben.", sourceObjective = "Trefft Euch mit Yanas Seestoß am Trockendock und baut einen weiteren Zerstörer. Sobald der Zerstörer bereit ist, schickt ihn auf eine neue Mission.", progress = "Habt Ihr den Ersatzzerstörer gebaut?", completion = "Ihr habt das Blatt tatsächlich gewendet, Kommandant. Großartig!", sourceObjectiveStatus = "unverified-source-field" }
quests[39656] = { id = 39656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsrudel im Visier", description = "Es ist an der Zeit, das Rudel anzugreifen! Ich habe die Kanone schon vorgeladen. Jetzt müsst Ihr nur noch zielen und schießen.\n\nDie Kleintiere dürften die Explosion überleben und davonlaufen. Die Heuler werden von den Kleintieren abgelenkt, und ihr habt dann freies Schussfeld auf die Anführer des Rudels.\n\nWeidmannsheil!", sourceObjective = "Feuert die handliche Kleintierkanone in der Nähe von Wolfsrudeln ab, damit sie auseinanderlaufen. Dadurch lassen sich die Anführer isolieren.", progress = "Die handliche Kleintierkanone ist geladen und einsatzbereit! Zielt einfach auf eines der Rudel in der Nähe. Die Rudelanführer sind leichte Beute, wenn die Heuler erst einmal abgelenkt sind.", completion = "Ihr habt es ohne einen Kratzer zurückgeschafft! Offenbar haben sich die Probleme des letzten Prototyps, der regelmäßig nach hinten losgegangen ist, von selbst erledigt.\n\nNoch ein paar Feinjustierungen und ich würde sagen, dass diese Kanone massenproduktionstauglich ist. Danke für die Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39657] = { id = 39657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[39658] = { id = 39658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk" }
quests[39659] = { id = 39659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[39661] = { id = 39661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhle des Lebensquells", description = "Die Drogbar haben meine Höhle überrannt. Dort praktizieren wir Flussmähnen unsere Wassermagie und schöpfen das reinste Heilwasser des Hochbergs.\n\nTrefft mich dort und lasst uns diesen heiligen Ort gemeinsam von diesen Bewohnern des Dunkels befreien.", sourceObjective = "Trefft Jale Flussmähne an der Höhle des Lebensquells.", completion = "Seid Ihr bereit? Wir werden gleich eine Höhle betreten... und die Drogbar sind an solch dunklen Orten zu Hause.", sourceObjectiveStatus = "unverified-source-field" }
quests[39663] = { id = 39663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod naht auf teuflischen Schwingen", description = "Es wird Zeit. Wir haben den Truppen der Legion einen vernichtenden Schlag zugefügt, von dem sie sich nie erholen werden.\n\nJetzt tragen wir den Kampf zu Tyrannas Kommandozentrale. Schnell, kümmert Euch um eine Flugmöglichkeit.", sourceObjective = "Lasst Euch von Izal Weißmond eine Teufelsfledermaus geben und fliegt hinauf zur Teufelshammer.", completion = "Könnt Ihr ihre Macht spüren? Ihr werdet jeden Kämpfer brauchen.\n\nDennoch... kümmere ich mich jetzt besser darum, wie wir hier heil wieder herauskommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39665] = { id = 39665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahrer Marinekommandant", description = "Ja! Das sind die Baupläne, die ich vergessen hatte, als ich letzte Woche dort angeln war. Diese Anweisungen decken sich eins zu eins mit meinem Prototyp. Nehmt diesen Heizkessel mit und installiert ihn auf einem unserer Schiffe. Damit sollten wir die Seeblockade durchbrechen und unsere Kontrolle auf die Meere Draenors ausweiten können.", sourceObjective = "Installiert den Heizkessel auf Eurem Schiff und schließt die Seeblockadenmission ab.", progress = "Habt Ihr die Aufrüstung abgeschlossen?", completion = "Ausstattungsteile sind auf hoher See wirklich entscheident.", sourceObjectiveStatus = "unverified-source-field" }
quests[39666] = { id = 39666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flotte Ausstattung", description = "Kommandant, unsere Flotte wird speziell angefertigte Marineausstattung benötigen, wenn wir in diesem Krieg eine Chance haben wollen. Spürt Seebär Jorren unten bei den Docks auf. Er sollte uns helfen können.", sourceObjective = "Trefft Euch mit Seebär Jorren an den Docks.", progress = "Ja?", completion = "Ausstattung kann dort draußen wirklich das Zünglein an der Waage sein. Schauen wir mal, was ich für Euch tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[39667] = { id = 39667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Lyndras hin: Leyflammenraub", description = "Die Wachen hier müssen Lyndras bemerkt haben. Und auch die Leystaubspur kann man kaum übersehen.\n\nVielleicht weiß eine der Wachen, wo Lyndras hin ist.", sourceObjective = "Fragt die Wachen der Violetten Festung nach Lyndras.", completion = "Ihr seid auf der Suche nach diesem verrückten Elfen? Tut mir leid, aber der wurde weggesperrt.\n\nWir haben ihn in der Ecke kauernd gefunden, wo er so komische Geräusche von sich gegeben hat. Als wir uns ihm dann genähert haben, hat er eine der Wachen angegriffen.\n\nAußerdem führte er einen als gestohlen gemeldeten Gegenstand bei sich. Uns blieb nichts anderes übrig, als ihn in der Violetten Festung einzusperren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39668] = { id = 39668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was für fiese Geschenke!", description = "Dieser fiese alte Grumpus hat eine Sammlung eigenartiger Geschenke angehäuft. Er versucht hartnäckig die Festtagsstimmung von Kindern überall zu brechen, indem er die schlimmsten denkbaren Geschenke verteilt.\n\nNehmt diese Stimmungsbombe und zerstört damit einige von Grumpus' ungewöhnlichen Geschenken!\n\nIch stehe voll hinter Euch, {name}. Nun geht und rettet die Festtagsstimmung!", sourceObjective = "Zerstört 5 ungewöhnliche Geschenke.", completion = "Uff, das waren ein paar fiese Geschenke. Vielleicht solltet Ihr Euch... äh... waschen. Wer weiß, was in einigen dieser Pakete drin war.", sourceObjectiveStatus = "unverified-source-field" }
quests[39670] = { id = 39670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleintierstreuschuss", description = "Die Heuler dieser Hügel ziehen in Rudeln umher. Drei gegen einen ist kein Kampf, den ich anfangen würde.\n\nGlücklicherweise sind diese Wölfe meinen Ingenieursfertigkeiten nicht gewachsen! Ich habe gerade dem Prototyp einer neuen Vorrichtung den letzten Schliff verliehen, die diese Rudel auseinandertreiben wird. Alles, was ich jetzt brauche, ist Munition...\n\nFangt mir ein paar Hasen auf der Lichtung südlich von hier und ich werde Euch gestatten, <der Erste/die Erste> zu sein, <der/die> die Kanone ausprobieren darf.", sourceObjective = "Fangt Hasen auf der Sonnenfrostlichtung.", progress = "Habt Ihr die Hasen schon eingefangen?", completion = "Hrm, diese Hasen sind ein wenig größer, als ich dachte. Ach, es sollte mir trotzdem gelingen, ein paar von ihnen in die Kanone zu stopfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39671] = { id = 39671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guards and Criswold" }
quests[39674] = { id = 39674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähne zusammenbeißen und noch mal versuchen!", description = "Das U-Boot hatte offensichtlich mehr Feuerkraft, als wir dachten! Sie haben einen Erstschlag gegen uns geführt, bevor wir überhaupt reagieren konnten.\n\nDer Verlust von Schiffen gehört bei Seeschlachten dazu, Kommandant. Zum Glück sind wir auf genau solch eine Situation vorbereitet. Sprecht mit Solog unten an den Trockendocks. Er dürfte uns helfen können, schnell einen neuen Zerstörer zu produzieren. Kommt zurück, wenn das Schiff bereit ist, und wir werden eine neue Mission für Euch haben.", sourceObjective = "Trefft Euch mit Solog Roark am Trockendock und baut einen weiteren Zerstörer. Sobald der Zerstörer bereit ist, schickt ihn auf eine neue Mission.", completion = "Ihr habt das Blatt tatsächlich gewendet, Kommandant. Großartig!", sourceObjectiveStatus = "unverified-source-field" }
quests[39675] = { id = 39675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flotte Ausstattung", description = "Kommandant, unsere Flotte wird speziell angefertigte Marineausstattung benötigen, wenn wir in diesem Krieg eine Chance haben wollen. Spürt Kronk Rostfunk unten bei den Docks auf. Er sollte uns helfen können.", sourceObjective = "Trefft Kronk Rostfunk bei den Docks.", progress = "Ja?", completion = "Ausstattung kann dort draußen wirklich das Zünglein an der Waage sein. Schauen wir mal, was ich für Euch tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[39676] = { id = 39676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahrer Marinekommandant", description = "Ja! Das sind die Baupläne, die ich vergessen hatte, als ich letzte Woche dort angeln war. Diese Anweisungen decken sich eins zu eins mit meinem Prototyp. Nehmt diesen Heizkessel mit und installiert ihn auf einem unserer Schiffe. Damit sollten wir die Seeblockade durchbrechen und unsere Kontrolle auf die Meere Draenors ausweiten können.", sourceObjective = "Installiert den Heizkessel auf Eurem Schiff und schließt die Seeblockadenmission ab.", progress = "Habt Ihr die Aufrüstung abgeschlossen?", completion = "Ausstattungsteile sind auf hoher See wirklich entscheident.", sourceObjectiveStatus = "unverified-source-field" }
quests[39680] = { id = 39680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Hammer, kein Frieden", description = "{name}, ich fürchte, dass mein Geist an diesen Ort gebunden bleibt, solange ich nicht wiederhergestellt bin.\n\nVor langer Zeit habe ich eine Höhle nahe der Küste hinter der Rabenwehr entdeckt. Als ich die Höhle erkundete, wurde ich von einer abscheulichen Kreatur angegriffen und ließ auf der Flucht meinen Hammer fallen.\n\nIch muss diesen Hammer zurückhaben, wenn ich Frieden finden will.", sourceObjective = "Bringt Saris' Hammer zurück zu seinem Laden.", progress = "Habt Ihr meinen Hammer finden können?", completion = "Ich danke Euch, {name}. Mit Worten kann ich meiner Dankbarkeit kaum Ausdruck verleihen.\n\nUnd darum möchte ich Euch ein Geschenk des Wissens geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[39681] = { id = 39681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eigenschaften von Leystein", description = "So etwas wie dieses \"Leysteinerz\" habe ich noch nie gesehen. Es ist so leicht wie Mithril, aber es birgt viel mehr magische Energie... sogar mehr als Saronit oder Elementium.\n\nVersuchen wir doch, etwas daraus herzustellen. Wie wäre es mit einem hübschen Paar Stulpen?", sourceObjective = "Seht Alard bei seinen Versuchen zu, das Leysteinerz zu verarbeiten.", completion = "Alles in Ordnung bei Euch? Die meisten meiner Materialien scheinen von den Flammen verschont geblieben zu sein. Nur gut, dass dies hier keine Schneiderei ist.\n\nDie Explosion wurde offensichtlich durch das Hinzufügen des Fluxes hervorgerufen.\n\nAber ohne Flux kein Schweißen. Das ist eine Schande. Wenn wir nicht schweißen können, müssen wir uns auf Gürtel und Armschienen beschränken.", sourceObjectiveStatus = "unverified-source-field" }
quests[39682] = { id = 39682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein teuflischer Ritt", description = "Ihr habt Maiev gehört. Wir müssen hier verschwinden.\n\nEs gibt einen Aufzugschacht am anderen Ende dieser Gewölbe. Wir müssen ihn erreichen.", sourceObjective = "Fliegt auf einer Teufelsfledermaus zum oberen Teil des Verlieses.", completion = "Kayn und Altruis unterrichteten mich bereits über Euer Kommen. Gerade zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39683] = { id = 39683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stählende Flammen", description = "Der gefürchtete Dämon Immolanth eroberte mit einer Armee der Legion eine entfernte Nexuswelt.\n\nDie Wächter konnten ihn in Ketten legen und in der Kammer zu unserer Linken einkerkern. Noch ist er gefangen, aber nicht für ewig.\n\nDie Macht dieses Dämons wäre wohl jedem Dämonenjäger einen Kampf wert. Wer auch immer ihn besiegen kann, erhält unvorstellbare Macht.\n\nIch denke, Ihr seid dieser Aufgabe gewachsen, {name}.", sourceObjective = "Tötet Immolanth und beansprucht seine Macht.", completion = "Ja... seht Euch an... Ihr pulsiert geradezu vor neuer Macht und neuem Wissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39684] = { id = 39684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasershow", description = "Im Osten befindet sich eine komplizierte Gefängniskammer, die einen Betrachter namens Starrer halten soll.\n\nKurz nach dem Durchbruch begann sie zu versagen.\n\nDie Spiegel im Raum müssen so ausgerichtet werden, dass sie einen Energiestrahl direkt auf die Kreatur lenken. Sein Schild kann ohne diesen Strahl unmöglich durchdrungen werden.\n\nBeeilt Euch. Altruis ist vorausgegangen, um die anderen zu unterstützen, aber sie werden nicht mehr lange durchhalten.", sourceObjective = "Durchbrecht den Schild des Starrers.", completion = "Ich habe keine Sekunde an Euch gezweifelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39685] = { id = 39685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefroren in der Zeit", description = "Die Wächterinnen haben vielerlei gefährliche Monster in dem Verlies eingesperrt. Doch nun, nachdem Gul'dans Streitkräfte eingedrungen sind, wird dies etwas... problematisch.\n\nViele unserer Truppen sind damit beschäftigt, einen furchterregenden Magmazerstörer in der südlichen Kammer in Schach zu halten. Da wir gerade erst aus der Stasis erwacht sind, haben wir keine Möglichkeit, ihn auszuschalten. Aber möglicherweise können wir das Eindämmungsfeld des Raums reaktivieren.\n\nGeht und findet Kayn. Tut, was immer notwendig ist, um diese Kammer zu versiegeln!", sourceObjective = "Aktivert die Gegenmaßnahmen in der Eiskammer.", completion = "Ich wusste, Ihr würdet es schaffen, {name}. Diese Kreatur darf nicht entkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39686] = { id = 39686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht aufwärts", description = "Kor'vas ist vorausgegangen, um zu Kayn und Altruis zu stoßen.\n\nNehmt den Aufzug, sobald er eintrifft, und trefft sie im Richthof der Wächterinnen über uns.", sourceObjective = "Nehmt den Aufzug zum Richthof der Wächterinnen.", completion = "Das ist tödlicher Ernst. Ihre tiefsten Überzeugungen stehen in direktem Konflikt.\n\nIch fürchte, dieses Duell wird nur auf eine Weise enden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[39688] = { id = 39688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freiheit ist zum Greifen nah", description = "Unsere übrigen Überlebenden haben sich bis in die letzte Kammer vorgekämpft.\n\nNun steht nur noch einer zwischen uns und dem Ausgang des Verlieses – der Anführer der dämonischen Invasionstruppen, Bastillax.\n\nTötet ihn, beansprucht seine Macht und befreit uns.", sourceObjective = "Tötet Bastillax und beansprucht seine Macht.", completion = "Wir sind aus dem Verlies entkommen, doch unser Werk ist noch nicht vollbracht.\n\nDer Angriff der Legion auf diese Welt hat gerade erst begonnen.\n\nWenn Azeroth das überstehen soll, müssen wir uns wohl mit diesem... Erzmagier Khadgar verbünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39689] = { id = 39689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari, wir brechen auf!", description = "Die Legion hat ihre Invasion unserer Welt begonnen. Überall in Kalimdor und den Östlichen Königreichen folgen tapfere Verteidiger dem Ruf zu den Waffen.\n\nDoch ohne Eure Hilfe werden sie schlussendlich scheitern. Ihr Illidari wurdet zu Waffen geschmiedet, um der Legion Einhalt zu gebieten.\n\nBitte begleitet mich. Alles weitere werdet Ihr auf der anderen Seite erfahren.", sourceObjective = "Sprecht mit Erzmagier Khadgar.", completion = "Wenn Ihr soweit seid, bringe ich Euch an Euer Ziel.\n\nSeid Ihr bereit zum Aufbruch?", sourceObjectiveStatus = "unverified-source-field" }
quests[39690] = { id = 39690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari, wir brechen auf!", description = "Die Legion hat ihre Invasion unserer Welt begonnen. Überall in Kalimdor und den Östlichen Königreichen folgen tapfere Verteidiger dem Ruf zu den Waffen.\n\nDoch ohne Eure Hilfe werden sie schlussendlich scheitern. Ihr Illidari wurdet zu Waffen geschmiedet, um der Legion Einhalt zu gebieten.\n\nBitte begleitet mich. Alles weitere werdet Ihr auf der anderen Seite erfahren.", sourceObjective = "Sprecht mit Erzmagier Khadgar.", completion = "Wenn Ihr soweit seid, bringe ich Euch an Euer Ziel.\n\nSeid Ihr bereit zum Aufbruch?", sourceObjectiveStatus = "unverified-source-field" }
quests[39691] = { id = 39691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Krieges", sourceObjective = "Sprecht mit Jace Düsterweber in der Burg Sturmwind.", completion = "Es herrschen jetzt düstere Zeiten in Sturmwind, {name}.\n\nNachdem König Varian Wrynn an der Verheerten Küste gefallen ist, scheinen die Anführer der Allianz angespannt und verunsichert zu sein.\n\nDer Zeitpunkt dieser Tragödie kann kein Zufall sein. Es ist typisch für die Brennende Legion, dass sie Chaos in den Reihen ihrer Feinde schürt und sie so von innen schwächt.\n\nWir müssen handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[39692] = { id = 39692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Krieges", description = "Kriegshäuptling Vol'jin erwartet euch.\n\nBetretet die Feste Grommash vor Euch und stellt Euch vor.", sourceObjective = "Sprecht mit dem Kriegshäuptling.", sourceObjectiveStatus = "unverified-source-field" }
quests[39694] = { id = 39694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freiheit ist zum Greifen nah", description = "Unsere übrigen Überlebenden haben sich bis in die letzte Kammer vorgekämpft.\n\nNun steht nur noch einer zwischen uns und dem Ausgang des Verlieses – der Anführer der dämonischen Invasionstruppen, Bastillax.\n\nTötet ihn, beansprucht seine Macht und befreit uns.", sourceObjective = "Tötet Bastillax und beansprucht seine Macht.", completion = "Wir sind aus dem Verlies entkommen, doch unser Werk ist noch nicht vollbracht.\n\nDer Angriff der Legion auf diese Welt hat gerade erst begonnen.\n\nWenn Azeroth das überstehen soll, müssen wir uns wohl mit diesem... Erzmagier Khadgar verbünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39695] = { id = 39695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Vantus Rune Used" }
quests[39696] = { id = 39696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", sourceObjective = "Hochlord, solange es den Orden der Silbernen Hand gibt, werden wir alles in unserer Macht Stehende tun, um die Stellungen der Legion in Azeroth zu vernichten.\n\nDamit wir Erfolg haben, müssen wir die Besten unseres Ordens verpflichten.\n\nErlaubt mir, als Erster in Eure Dienste zu treten, {name}. Ich werde in Eurer Abwesenheit die Aufgaben Eurer Augen und Eurer Klinge übernehmen und bis zu meinem letzten Atemzug gemäß Eurem Willen handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[39697] = { id = 39697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Offizier und Gentleman", description = "Ich habe ein wenig nachgebohrt – oder wie auch immer man das bei der Marine nennt... nachgeschnorchelt?\n\nGul'dan hat sein mächtiges Flaggschiff auf eine Erkundungsmission in die letzten Winkel Draenors geschickt. Er zeichnet die Leylinien in den Ozeanen auf. Mit diesen Informationen könnte ich Euren Ring verbessern... In Gul'dans Händen hingegen könnten sie katastrophale Folgen haben.\n\nMobilisiert die Flotte, {name}! Macht Jagd auf dieses berüchtigte Schiff, die Ruf des Meisters, und stehlt die Information, bevor sie sie abliefern können. Beeilt Euch!", sourceObjective = "Schließt die legendären Marinemissionen ab, bis Ihr die Ruf des Meisters besiegt und eine Seekarte Draenors erhalten habt.", progress = "Ich hoffe, die Ruf des Meisters hat nicht zu viele Eurer Schiffe auf den Meeresgrund geschickt.", completion = "Ja, ja! Genau darauf hatte ich gehofft! Diese Karte ist von unschätzbarem Wert. Indem wir diese Knotenpunkte am Meeresgrund triangulieren, können wir die wichtigsten Leylinien Draenors ausfindig machen. Hmmm... hier ist natürlich der Standort meines eigenen Turms. Außerdem scheint sich Energie in der Nähe von Karabor zu sammeln. Und hier am Thron der Elemente.\n\nOh, sehr gut. Wir werden damit sehr bald etwas anfangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[39698] = { id = 39698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspektion", description = "Wie Ihr seht, haben wir keine Mühen gescheut, um Euch bei Eurer großen Aufgabe zu unterstützen.\n\nGerade werden die letzten Vorbereitungen getroffen. Kommt, begleitet mich ein Stück.", sourceObjective = "Begleitet Fürstin Sylvanas Windläufer und bereitet ihr Schiff auf das Ablegen vor.", progress = "Sobald die Vorbereitungen abgeschlossen sind, machen wir uns auf den Weg nach Sturmheim.", completion = "Versteht Ihr, wie wichtig unsere Aufgabe ist? Wenn wir nicht um unsere Zukunft kämpfen, haben wir keine mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[39699] = { id = 39699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyschmieden der Eisenhörner", description = "Ich spüre eine große Stärke in Euch, die Ihr nicht anzuwenden versteht. Wir Eisenhörner verwenden doppelt so viel Metall für unsere Waren wie andere Schmiede.\n\nUnd es gibt auch eine spezielle Hammertechnik, um so viel Leystein zu bearbeiten. Ich werde sie Euch zeigen.\n\nVerwendet unser Altmetall, um daraus Stulpenteile zu fertigen. Ich werde diese Teile dann zusammenschweißen.", sourceObjective = "Sammelt Altmetall in der Umgebung der Eisenhornenklave und verwendet dann Grünhufs Amboss und Schmelzofen, um Altmetallhandschützer, eine Altmetallhandplatte, eine Altmetallmanschettenplatte und 1 Altmetallfingerplatten herzustellen.", progress = "Ich warte, Fremder.", completion = "Ihr versteht Euch darauf, mit dem Hammer umzugehen, Fremder. Eure Fähigkeiten übersteigen die vieler anderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[39702] = { id = 39702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende der Rabenwehr", description = "{name}, habt Ihr bereits von Saris Flinkhammer gehört?\n\nEr war ein legendärer Schmied unter den Elfen der Rabenwehr. Ich frage mich, ob seine Forschungsarbeiten noch existieren.\n\nIch möchte, dass Ihr Euch dort hinbegebt und etwas über Saris herausfindet oder in seinem Laden nach Dingen sucht, die wir hier erforschen können.", sourceObjective = "Begebt Euch zur Rabenwehr und sucht nach Saris Flinkhammer.", completion = "Danke, dass Ihr mich befreit habt, Fremder. Ihr möchtet also etwas über die Schmiedekunst lernen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39709] = { id = 39709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
