quests[39712] = { id = 39712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistletoe and Stockings" }
quests[39713] = { id = 39713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39716] = { id = 39716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die platzenden Gruselkürbisse", description = "Die Knochenflotte überfiel einst Handelsschiffe, die die Meere Draenors bereisten und eines dieser Schiffe transportierte Saatgut nach Elodor.\n\nEbendiese Saat verwenden sie nun, um unseren Boden zu verseuchen und daraus wuchernde Abscheulichkeiten sprießen zu lassen. Diese Monstrositäten müssen vernichtet werden, bevor sie sich ausbreiten können.", sourceObjective = "Tötet 6 wachsende Gruselkürbisse.", completion = "Das hat bestimmt Spaß gemacht, die Dinger zu zermatschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39717] = { id = 39717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Mission Complete" }
quests[39718] = { id = 39718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Paradies", description = "Erzmagier Khadgar plant eine Expedition nach Azsuna. Ihr solltet ihn unverzüglich an Krasus' Landeplatz in Dalaran aufsuchen.", sourceObjective = "Sprecht mit Erzmagier Khadgar bei Krasus' Landeplatz in Dalaran.", completion = "Perfekt. Wie wär's mit einem Ausflug nach Azsuna?", sourceObjectiveStatus = "unverified-source-field" }
quests[39719] = { id = 39719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meuterei auf dem Knochenschiff", description = "Jedes Jahr um diese Zeit wird Draenor von einer seltsamen Woge geisterhafter Energie heimgesucht. Von diesem Phänomen angezogen, erscheint eine Geisterflotte untoter Piraten aus den Nebeln. Wir nennen sie die Knochenflotte.\n\nDie Knochenflotte wird von einem ruchlosen Piraten kommandiert, der auf den Namen Knochenschinder hört. Sein einziges Bestreben liegt in der vollständigen Vernichtung allen Lebens auf Draenor.\n\nSpürt ihn auf und setzt ihm ein Ende, bevor er wieder in den Nebeln verschwindet.", sourceObjective = "Tötet Knochenschinder.", completion = "Endlich wurde er auf den Meeresgrund zurückgeschickt. Wir werden ihn sicher wiedersehen, doch heute feiern wir!", sourceObjectiveStatus = "unverified-source-field" }
quests[39720] = { id = 39720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fauler Dünger", description = "Die Knochenflotte will nichts mehr, als ihren Fluch der Untoten immer weiter ins Land hinein zu verbreiten. Wie eine Krankheit wird er langsam die Landschaft übernehmen, wenn man ihn nicht eindämmt.\n\nDer Gestank der Untoten dringt aus den Düngefässern, die sie benutzen, um damit ihre furchtbare Saat zu säen. Sie sind die Quelle, von der aus sich die Seuche verbreitet, und sie müssen zerstört werden.", sourceObjective = "Zerstört 8 Fässer mit Schreckensdünger.", completion = "Wenn man bedenkt, was in normalem Dünger drin ist, will ich gar nicht wissen, woraus DAS Zeug besteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39721] = { id = 39721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entsatzung", description = "Wenn wir Draenor vor der Bedrohung der Knochenflotte schützen wollen, müssen wir ihre Besatzung ausdünnen.\n\nDezimiert sie schnell und gezielt und vielleicht drängen wir sie für ein weiteres Jahr auf See zurück.", sourceObjective = "Erledigt 12 Besatzungsmitglieder des Knochenschiffs.", completion = "Bloß gut, dass Ihr da wart und Euch dieser Knochenkanaillen angenommen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[39722] = { id = 39722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden neuer Stärke", description = "Selbst die ruchlosesten Fürsten der Legion fürchten sich auf dem Schlachtfeld vor Euch. Dennoch schaffen sie ohne Unterlass immer furchtbarere Schrecken und Unholde, in der Hoffnung, Eurer Stärke etwas entgegensetzen zu können.\n\nHochlord, wir müssen Eure Macht verstärken, um die Oberhand zu behalten.\n\nDer Altar vor Euch enthält die Essenz unzähliger Helden des Lichts, die in diesen heiligen Hallen bestattet wurden. Platziert Eure Waffe darauf und verleiht ihr dadurch neue Stärke.", sourceObjective = "Erfüllt Eure Waffe mit neuer Macht.", completion = "Ich werde weiterhin das Licht anflehen, die Macht Eurer Waffe zu verstärken.\n\nIm Moment sollte die hinzugewonnene Stärke vollkommen ausreichend sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[39723] = { id = 39723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39724] = { id = 39724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39725] = { id = 39725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39726] = { id = 39726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungsraub", description = "Wenn Ihr wirklich Interesse an meinen Forschungsarbeiten habt, dann müsst Ihr sie zurückbeschaffen. Aus meinem Laden wurde nämlich alles gestohlen, was ich je gefertigt habe.\n\nDie Brustplatten der Rabenwehrsoldaten waren meine Meisterstücke. Sie sind leicht, aber dennoch widerstandsfähig, und sie bieten große Beweglichkeit.\n\nWenn Ihr meinen verderbten Brüdern und Schwestern ihre Brustplatten abnehmt und sie mir zurückbringt, erläutere ich Euch die Feinheiten der Fertigung.", sourceObjective = "Sammelt 5 Rabenwehrbrustplatten von den Elfen der Rabenwehr.", progress = "Habt Ihr meine Brustplatten schon besorgt?", completion = "Diese Exemplare stellen gute Beispiele dar. Jetzt will ich Euch zeigen, wie ich sie hergestellt habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[39727] = { id = 39727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39728] = { id = 39728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39729] = { id = 39729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Rabenwehr", description = "Ihr habt mich mit Eurer Hilfe geehrt, und jetzt möchte ich mich für die Gefallen revanchieren. Auf dem Podest dort findet ihr meine gesammelten Forschungsaufzeichnungen. Nehmt sie mit und lernt davon, damit Ihr mein Erbe fortführen könnt.\n\nNochmals vielen Dank, {name}.", sourceObjective = "Bringt Saris' Aufzeichnungen zu Alard in Dalaran.", progress = "Habt Ihr ihn finden können?", completion = "Das... das ist wirklich unglaublich! Da sind Verfahren dabei, die ich nie für möglich gehalten hätte. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[39730] = { id = 39730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Mission Complete" }
quests[39731] = { id = 39731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der friedvolle Forst", description = "Erzmagier Khadgar hat uns vor Kurzem Informationen über Val'sharah zukommen lassen. Es scheint gute Neuigkeiten zu geben.\n\nIhr solltet ihn so bald wie möglich auf Krasus' Landeplatz in Dalaran aufsuchen.", sourceObjective = "Sprecht mit Erzmagier Khadgar auf Krasus' Landeplatz in Dalaran.", completion = "<Erzmagier Khadgar lächelt.>\n\nIch komme nicht oft in Verlegenheit, dies zu sagen, aber ich habe gute Nachrichten für Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39732] = { id = 39732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Mission Complete" }
quests[39733] = { id = 39733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einsame Berg", description = "Unsere Quellen haben uns berichtet, dass ein Abgesandter der Hochbergtauren vor Kurzem in Dalaran eingetroffen ist. Seine Absichten sind noch nicht bekannt, aber die Tauren könnten Verbündete von unschätzbarem Wert in dieser Gegend sein.\n\nKhadgar wird den Abgesandten bei Krasus' Landeplatz in Dalaran empfangen. Ihr solltet Euch auch dort einfinden.", sourceObjective = "Sprecht mit Kriegerheld Oro an Krasus' Landeplatz in Dalaran.", completion = "Seid gegrüßt, Champion. Ich bin Kriegerheld Oro von den Hochbergtauren. Ich bin auf den Winden des Krieges hierhergekommen, um Euch zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39734] = { id = 39734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Mission Complete" }
quests[39735] = { id = 39735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmheim", description = "Himmelsadmiralin Rogers lässt ausrichten, dass Ihr sie in Dalaran treffen möchtet.\n\nSie erwartet Euch in der Violetten Zitadelle. Es klang, als sei es dringend.", sourceObjective = "Sprecht mit Himmelsadmiralin Rogers in der Violetten Zitadelle in Dalaran.", completion = "Es ist mir eine Ehre, {name}.", sourceObjectiveStatus = "unverified-source-field" }
