quests[39740] = { id = 39740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39741] = { id = 39741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In unsere Reihen", description = "Ich finde, wir sollten Akama schleunigst in unsere Reihen aufnehmen. Die anderen müssen unbedingt sehen, dass er als einer von uns behandelt wird und nicht als Außenseiter.\n\nKor'vas Blutdorn hat immer wieder unter Beweis gestellt, dass sie von unschätzbarem Wert ist. Ihre Kampffertigkeiten sind unbestreitbar und beispiellos. Ihr werdet keinen besseren Champion finden, um unsere Feinde zu vernichten.\n\nEs wird Zeit, sie offiziell als Champions anzuerkennen.", sourceObjective = "Rekrutiert Akama und Kor'vas Blutdorn als Eure Champions.", completion = "Bisher waren die Illidari ein ziemlich exklusiver Verein. Ausschließlich {class}. Doch wie Ihr so deutlich gezeigt habt, mein Lieber, ist die Aufnahme von Akama ein wichtiger Schritt, um voranzukommen und uns gegenseitig vertrauen zu können.\n\nDas gibt Hoffnung.\n\nUnd es versteht sich natürlich von selbst, dass Ihr Kor'vas zu einem Eurer Champions macht. Niemand kämpft so gut wie sie.\n\nWas ist da los?", sourceObjectiveStatus = "unverified-source-field" }
quests[39742] = { id = 39742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen" }
