quests[39745] = { id = 39745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar Teleport" }
quests[39746] = { id = 39746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungebrochener Ring", description = "Wir haben eine empfindliche Niederlage an der Verheerten Küste erlitten. Die Brennende Legion verfügt jetzt über eine Stellung auf Azeroth, und unsere besten Armeen müssen sich zerschmettert zurückziehen.\n\nDie Ältesten des Irdenen Rings haben eine Notratssitzung in der Nähe des Herzens unserer Welt einberufen, am Mahlstrom. {name}, Eure Triumphe in ganz Azeroth und auf Draenor sind legendär. Jetzt brauchen wir Euch mehr als je zuvor.\n\nStoßt am Mahlstrom zu mir. Sturmruferin Mylra wird in Kürze dorthinfliegen. Ihr findet sie an Krasus' Landeplatz hier in Dalaran.", sourceObjective = "Helft den Schamanen des Irdenen Rings am Mahlstrom. Sturmruferin Mylra wird Euch von Krasus' Landeplatz in Dalaran aus dorthinfliegen.", completion = "Ich danke Euch, {name}. Ihr habt mich gerettet. Ihr habt uns alle gerettet.\n\nIch hatte keine Chance... Meine Beziehung zu den Elementen hat sich seit den Ereignissen in Draenor verändert. Ich muss mich auf eine Seelensuche begeben. {name}, Ihr müsst den Irdenen Ring ohne mich anführen. Ihr seid der Anführer, den er jetzt braucht.", sourceObjectiveStatus = "unverified-source-field" }
