quests[39753] = { id = 39753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[39756] = { id = 39756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein solider Plan", description = "Die Legion glaubt, wir wären noch von der Verheerten Küste geschwächt. Sie denkt, wir könnten uns nicht wehren.\n\nLasst uns den Dämonen das Gegenteil beweisen.\n\nWir arbeiten hart daran, uns einen Überblick über die Verheerten Inseln zu verschaffen und möglichst viele Informationen über jede ihrer Regionen zu sammeln, um unseren Angriff vorzubereiten.\n\nWenn Ihr Euch mit der Karte vertraut gemacht habt, solltet Ihr sofort nach Dalaran aufbrechen und Euch in die Höhle des Löwen wagen.\n\nWir werden diesem Wahnsinn ein für alle Mal ein Ende bereiten. Das Licht stehe uns bei.", sourceObjective = "Wählt Euren ersten Angriffspunkt auf den Verheerten Inseln aus.", completion = "Viel Glück da draußen! Wir stehen das gemeinsam durch.", sourceObjectiveStatus = "unverified-source-field" }
quests[39757] = { id = 39757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge schärfen", description = "Seid gegrüßt, <Todesgebieter/Todesgebieterin>. Auch wenn die Klingen in Euren Händen prachtvoll sein mögen, verfügen sie doch über viel ungenutztes Potenzial. Wenn Ihr die Seelen Eurer Feinde erntet, wird die Macht der Klingen wachsen.\n\nGroßmeister Corvus hat neue Techniken studiert, die Euch vielleicht helfen könnten.\n\nEr arbeitet an den Schmieden im oberen Bereich.", sourceObjective = "Sprecht mit Großmeisterbelagerungsschmied Corvus in Acherus.", completion = "Ah, diese Waffe ist fantastisch! Seht Ihr, wie die Seelen der Verdammten entlang der Schneide tanzen? Oh, wie sehnsüchtig sie nach Befreiung rufen!\n\nJa... in ihnen sehe ich die zukünftige Form der Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[39758] = { id = 39758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Fighters Active" }
quests[39759] = { id = 39759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creepy Crawlers Active" }
quests[39761] = { id = 39761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittenes Runenschmieden", description = "Ich arbeite schon seit vielen Jahren daran, die Schmieden zu verbessern. Diese Waffe wird eine perfekte Demonstration der neuesten Version der Seelenschmiede!\n\nWir können Euer Artefakt zur Schmiede bringen und so umformen, dass Ihr die enthaltene Macht nutzen könnt, sofern Ihr die Waffe zuvor mit reichlich Seelen speist. Lasst es uns einfach mal probieren, ja?", sourceObjective = "Nutzt die Seelenschmiede, um Eurem Artefakt Macht zu verleihen.", completion = "Oh ja... das wird klappen!\n\nKommt zurück, wenn Ihr Eurer Klinge noch ein Festmahl der Seelen gegönnt habt, dann werden wir die mächtigste Waffe aller Zeiten erschaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39762] = { id = 39762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feltotem Warlock" }
quests[39763] = { id = 39763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Teufel mit den Maschinen", description = "<Matthew mustert Euch leise knurrend von oben bis unten.>\n\nIhr wollt, dass ich Euch etwas über diesen Stein erzähle? Dann müsst Ihr zunächst etwas für mich tun.\n\nDie Legion hat eine große Anzahl ihrer Teufelsmaschinen mitgebracht, um diese Welt zu erobern. Diese Maschinen werden durch Kerne voller Teufelsenergie angetrieben und von niederen Dienern transportiert.\n\nBringt mir ein paar dieser Kerne. Dann bekommt Ihr die Informationen, die Ihr benötigt.", sourceObjective = "Besorgt 10 Teufelsenergiekerne von Wyrmzungendienern in Suramar. Wenn Ihr genug eingesammelt habt, bringt sie zu Matthew nach Dalaran.", progress = "Habt Ihr, worum ich Euch gebeten habe?", completion = "<Matthew heult begeistert auf.>\n\nSehr beeindruckend.", sourceObjectiveStatus = "unverified-source-field" }
quests[39764] = { id = 39764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzend aber tödlich", description = "Seelenbewahrer Uriah und ich haben Dämonengefangene zu Allari in Azsuna gebracht, als unsere Karawane von Kobolden angegriffen wurde.\n\nDieses hirnlose Gesindel ist mit den Seelenkammern verschwunden, in denen sich unsere dämonischen Gefangenen befanden.\n\nDie Kristalle glänzen zwar hübsch, aber sie sind auch tödlich. Wenn sie auch nur im Geringsten beschädigt werden, könnten die darin gefangenen Dämonen entkommen.\n\nBegebt Euch in die Höhle, die sich in der Nähe befindet, und bergt die Seelenkammern, bevor es zu spät ist.", sourceObjective = "Sammelt Seelenkammern von Kobolden im Schnodderschnauzenbau.", progress = "Habt Ihr die Seelenkammern schon geborgen?", completion = "Ist das alles, was Ihr finden konntet?\n\nIch bin natürlich dankbar, diese Edelsteine wieder in meinem Besitz zu haben, aber scheinbar fehlen immer noch einige. Ich fürchte, sie wurden zerbrochen, was bedeutet, dass die Dämonen daraus entwischt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[39765] = { id = 39765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftragen und polieren", description = "In den Jahrhunderten, die ich schon tot bin, wurde mein Grab noch nie so geschändet... Der Anführer der hiesigen Kobolde hat meinen Schädel aus dem Grab gestohlen und trägt ihn auf dem Kopf!\n\nEr ist in der Höhle da unten, aber der Weg ist durch ein Tor versperrt. Kobolde erkennen ihre Anführer anhand der von ihnen getragenen Schädel an und sind dämlich genug, auch Euch für einen Anführer zu halten, wenn Ihr einen Schädel aufsetzt.\n\nTötet einen ihrer Schädelhauptmänner und holt Euch seinen Schädel des Herumkommandierens – dann lassen sie Euch vielleicht in die Höhle.", sourceObjective = "Beschafft den Schädel des Herumkommandierens vom Schädelhauptmann der Blaukerzen.", progress = "Diese Schändung...", completion = "Ich denke, das wird perfekt funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39766] = { id = 39766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Worm" }
quests[39767] = { id = 39767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleigh and Snowfighters" }
quests[39768] = { id = 39768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabkerzen", description = "Diese Kobolde nutzen die Angriffe gegen den Stamm der Himmelshörner schamlos aus. Sie schänden unsere Gräber und stehlen alles, was sie in die Pfoten bekommen.\n\nIch kann nichts tun, um sie aufzuhalten! Bitte befreit diese heilige Begräbnisstätte von den Kobolden.", sourceObjective = "Tötet 7 Grabräuber der Blaukerzen.", completion = "Einige von ihnen scheinen immerhin etwas weniger begeistert zu buddeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[39769] = { id = 39769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tore zum Wachs", description = "Geht, sprecht mit dem Torwächter der Blaukerzen und seht, ob er Euch zum Kerzenkönig vorlässt. Wenn Ihr vorbeigelassen werdet, weil Ihr den Schädel tragt, wird der Gestank es wert gewesen sein.", sourceObjective = "Sprecht mit dem Torwächter der Blaukerzen und seht, ob er Euch zum Kerzenkönig vorlässt.", completion = "Was will Stinker?", sourceObjectiveStatus = "unverified-source-field" }
quests[39771] = { id = 39771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme des Donners", description = "Der Weiße Tiger hat eine Reihe von Herausforderungen für jene vorbereitet, die die Waffen des Sturms erhalten möchten.\n\nIhr kennt jetzt ihre Macht. Es sind die Artefakte, die Ra-den höchstselbst im Zeitalter der Titanen geführt hat.\n\nKommt! Ich habe schon Arenateams aus drei Kontinenten zum Sieg geführt. Mit mir an Eurer Seite könnt Ihr nicht verlieren!", sourceObjective = "Reist zum Tempel des Weißen Tigers und beweist dort, dass Ihr würdig seid, die Waffen des Sturms zu führen!", progress = "Darauf haben wir uns unser ganzes Leben lang vorbereitet, {name}. Wir dürfen nicht versagen.", completion = "Ihr seid wahrhaft der Auserwählte, {name}. Ich würde mit Freuden mein Leben für Euch geben.\n\nWo immer Ihr den Irdenen Ring hinführt, werde ich Euch folgen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39772] = { id = 39772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Licht aufgegangen", description = "Okay, von mir aus du jetzt kannst sagen Hallo zu Kerzenkönig.", sourceObjective = "Beschafft Oenias Schädel vom Kerzenkönig.", progress = "Habt Ihr meinen Schädel gefunden?", completion = "Den Geistern sei Dank! Diese Kobolde ehren ihre Vorfahren nicht so, wie wir es tun. Jetzt kann ich in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39773] = { id = 39773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal des Seelenbewahrers", description = "Seelenbewahrer Uriah wurde beim Angriff der Kobolde verletzt, bestand aber darauf, noch tiefer in die Höhle vorzudringen, um die gestohlenen Seelensplitter zu bergen. Er befahl mir, mit unseren verbliebenen Vorräten hier zu warten, bis er zurückkehrt, aber ich befürchte das Schlimmste.\n\nBitte findet Uriah. Er ist der Einzige, der weiß, wie man die Dämonen festsetzen kann.", sourceObjective = "Findet Seelenbewahrer Uriah im Schnodderschnauzenbau.", completion = "Uriah würde nicht wollen, dass ich meine Zeit mit Tränen vergeude. Meine Trauer kann warten, bis die entflohenen Dämonen wieder eingefangen wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39774] = { id = 39774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenfestsetzung", description = "Die entflohenen Dämonen müssen wieder festgesetzt werden. Sie zu töten ist keine Option. Uriah wurde damit beauftragt, die Gefangenen zur Befragung zu Allari zu bringen, und ich werde nicht zulassen, dass er versagt.\n\nIch habe Uriah oft dabei zugesehen, wie er Dämonen einfing. Es erscheint... kompliziert, aber ich glaube, ich bekomme das hin. Ihr müsst sie nur zuerst für mich bezwingen.", sourceObjective = "Schwächt Dämonen, damit Lehrling Rosalyn sie mit einer Seelenkammer einfangen kann.", progress = "Ihr müsst die Dämonen schwächen, damit ich sie einfangen kann.", completion = "Danke für Eure Hilfe, {name}. Ich werde Uriahs Andenken ehren, indem ich unsere Reise nach Azsuna beenden und die Dämonengefangenen wie geplant an Allari übergeben werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[39775] = { id = 39775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmgeschmiedeter Greifhakenwerfer", sourceObjective = "Das sieht aus wie einer der Greifhakenwerfer, mit denen die hiesigen Vrykul die steilen Bergkämme in Sturmheim erklimmen.\n\nDer könnte sich noch als praktisch erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39776] = { id = 39776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfwürmer", description = "Das Dorf der Schneemähnen hinter uns wurde vom Ausmaß dieses Angriffs völlig überrumpelt. Ich werde versuchen, dem Angriff der Drogbar hier standzuhalten, um den Zivilisten genug Zeit für die Evakuierung zu verschaffen.\n\nDie Drogbar benutzen Würmer, die ihnen einen Weg zur Oberfläche graben, damit sie dann ihre Truppen in den Einsatz schicken können.\n\nIch übertrage Euch das Kommando über unsere Streitkräfte. Setzt sie ein, um diese Würmer zu töten, und verhindert so, dass der Feind Verstärkung erhält.", sourceObjective = "Tötet Naxa, Arxas und Xist.", completion = "Das sollte die Eindringlinge verlangsamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39777] = { id = 39777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschafft uns Zeit", description = "Wir brauchen Zeit, um das Dorf der Schneemähnen zu evakuieren. Könnt Ihr den Machtsteindrogbar entgegentreten und ihre Anzahl drastisch reduzieren?\n\nIch werde meine Heiler anweisen, jeden, der nicht kampffähig ist, in Sicherheit zu bringen.", sourceObjective = "Tötet 10 Machtsteindrogbar.", progress = "Wir brauchen jede Sekunde, die Ihr uns verschaffen könnt.", completion = "Ausgezeichnet. Ich danke Euch, Champion.\n\nDank Eurer Bemühungen ist es uns gelungen, die Kinder und Verwundeten in Sicherheit zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39780] = { id = 39780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Unterkönig", description = "Mayla ist dem Unterkönig bereits bis in dessen Höhle nachgejagt. Wir sagen unseren Kindern immer, dass sie das keinesfalls tun dürfen.\n\nLeichtsinniges Kind, aber hey, wer will schon ewig leben! Schließen wir uns ihr im Kampf an.", sourceObjective = "Greift Dargrul den Unterkönig an.", completion = "Dargrul zögert das Unvermeidliche nur hinaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[39781] = { id = 39781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Tod dem Unterkönig", description = "Ich werde meinen Leuten befehlen, einen Weg durch diese Trümmer zu ebnen und Dargruls Truppen direkt anzugreifen.\n\nWir werden eine List anwenden.\n\nNavarrogg hat einen vielversprechenden Plan vorgeschlagen. Er kennt einen Seiteneingang, der direkt zu Dargrul führen könnte.\n\nSammelt all Eure Verbündeten zusammen und greift die Feinde durch den Seiteneingang an. Stellt den Hammer von Khaz'goroth sicher, bevor dieser Schurke den Berg einstürzen lässt.\n\nWir werden für Ablenkung sorgen, damit Ihr ihn überraschen könnt.", sourceObjective = "Beschafft den Hammer von Khaz'goroth zurück.", progress = "Der Krieg geht weiter.", completion = "Es war ein harter, aber notwendiger Kampf. {name}, im Namen der Flussmähnen, der Himmelshörner und der Dunkelsteine danke ich Euch für Eure Bemühungen.\n\nDoch sobald eine Schlacht endet, beginnt die nächste. Wenn Ihr Euch der Brennenden Legion entgegenstellt, dann seid gewiss, dass die Stämme vom Hochberg an Eurer Seite stehen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39782] = { id = 39782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exiled Shaman" }
quests[39783] = { id = 39783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet - Terky" }
quests[39784] = { id = 39784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster Pao'lek" }
quests[39786] = { id = 39786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine zahnlose Wette", description = "Das zweite Ziel ist ein Basilisk namens Steinzahn. Er lebt am Ufer des nahe gelegenen Flusses.\n\nIch habe einen größeren Betrag auf ihn gesetzt. Wenn Ihr ihn also erlegen könnt, winkt Euch ein schöner Anteil.\n\nZum Beweis müsst Ihr mir seinen Kiefer bringen. Und beeilt Euch, bevor die Tauren ihn kriegen!", sourceObjective = "Erbeutet Steinzahns Kiefer von Steinzahn in der Steinnarbenschlucht.", progress = "Habt Ihr ihn erlegt?", completion = "Nun, ich hatte fast damit gerechnet, Eure Statue am Flussufer zu finden. Auf Euch wartet eine schöne Summe, wenn die Tauren erst zurück sind...\n\nIhr seid ihnen nicht vielleicht begegnet, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[39787] = { id = 39787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettmanipulation", description = "Wollt Ihr bei einer Wette einsteigen, <mein Lieber/meine Liebe>?\n\nDiese Tauren sind vom Himmelshorn und sie halten sich selbst für ziemlich gute Jäger. Ich habe ein hübsches Sümmchen darauf verwettet, dass sie es nicht schaffen, ein paar der größten Bestien Sturmheims zu erlegen.\n\nWenn Ihr diese Tiere erlegt, bevor die Tauren es schaffen, würde ich den Wettgewinn mit Euch teilen. Einverstanden?\n\nAls Erstes geht es um einen großen Adler, der im Vorgebirge lebt. Man nennt ihn Hassfeder. Ihr könnt ihn mit einem Stück Fleisch ködern, aber sein Horst befindet sich in ziemlicher Höhe, also benötigt Ihr eine Greifhakenkanone. Eigentlich müsste hier irgendwo eine herumliegen...", sourceObjective = "Lockt Hassfeder an und erlegt ihn, um seinen Schnabel im Sturmgepeitschten Vorgebirge zu erbeuten.", progress = "Habt Ihr meine Trophäe schon?", completion = "Ihr konntet ihn also erlegen, hm? Mann, da werden diese Tauren aber neidisch sein, wenn sie zurückkommen!\n\nNatürlich müsst Ihr auf Euren Anteil warten, bis die Tauren wieder da sind und ihre Wettschulden bezahlt haben. Aber bis dahin habe ich schon ein schönes, neues Ziel für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[39788] = { id = 39788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Runenwalds", description = "Die Knochensprecher... Sie sind verderbt... Sie dürsten nach Macht.\n\nTilgt sie aus meinen Wäldern...", sourceObjective = "Tötet 8 Runenäxte der Knochensprecher und 8 Schnitzer der Knochensprecher im Runenwald.", progress = "Wurde die Verderbnis entfernt?", completion = "Ohne diese Knochensprecher wird der Runenwald wieder zur Ruhe kommen.\n\nDas ist ein guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[39789] = { id = 39789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mithilfe gefragt", description = "Seid gegrüßt, <Reisender/Reisende>! Ihr könnt gerne in unserem Lager verweilen, aber wenn Ihr länger hierbleiben wollt, möchte ich Euch um Mithilfe bitten.\n\nBis jetzt hat uns dieses Land hier nämlich mit großzügiger Beute beschenkt. In letzter Zeit aber gibt es ein Problem mit den Worgs, denn sie dünnen die Herden viel zu sehr aus.\n\nIch kann mich nicht selbst um alle kümmern, darum setze ich ein Kopfgeld für jeden auf der Hochebene erlegten Worg aus. Kehrt zu mir zurück, wenn Ihr ihr Rudel etwas zurechtgestutzt habt.", sourceObjective = "Tötet 10 Dämmerpelzworgs in der Bernsturzebene.", completion = "Oh, hey! Ihr haltet bestimmt Ausschau nach den Tauren, die hier ihr Lager aufgeschlagen hatten, oder? Die sind gerade losgezogen, aber Schnacki und ich können uns ja um Euch kümmern!\n\nSie wollten Euch doch dafür bezahlen, ein paar Worgs zu erlegen, oder? Kein Problem!\n\nIch hab zwar nicht so viel Gold, dafür aber ein paar ziemlich wertvolle Waren. Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[39790] = { id = 39790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernoschwefeltheorie", description = "Ich habe alle von Euch zusammengetragenen Forschungsunterlagen gesichtet und dabei eine Theorie entwickelt. Wir wissen, dass sich das Erz auf dieser Welt durch Änderung der Druckverhältnisse und andere Umgebungsbedingungen weiterentwickelt.\n\nAber der Infernoschwefel bezieht sein beschleunigtes Wachstum aus dämonischer Energie, ganz ähnlich wie das Saronit aus Eiskrone.\n\nWenn wir das überprüfen wollen, benötigen wir die Hilfe eines Magienutzers.\n\nBring diesen Schwefel zu Matthew Rabis. Vielleicht weiß er, wie man ihm Leben einhauchen kann.", sourceObjective = "Bringt die Schwefelprobe zu Matthew Rabis in der Schattenseite.\n\nBereitgestellter Gegenstand:", completion = "<Schnüffel, schnüffel.> Irgendetwas riecht... dämonisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[39791] = { id = 39791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allerletzte Ruhe", description = "Ich möchte Euch um einen Gefallen bitten, <Fremder/Fremde>.\n\nWenn Ihr an den Gräbern der legendären Helden vorbeigeht, werdet Ihr sicher auf die Geister der ruhelosen Toten stoßen, die über die Missetaten der Knochensprecher sehr aufgebracht sind. Sie müssen wieder zurück in die Erde, in der sie begraben wurden, damit auch über sie ein Urteil gefällt werden kann.\n\nNehmt diesen Ast. Er enthält die Essenz des Runenwalds. Wendet seine Kraft auf einen geschwächten Geist an, um ihn wieder zur Ruhe zu bringen.", sourceObjective = "Verwendet den Ast des Runenwalds, um 8 geschwächte ruhelose Vorfahren wieder zur Erde zurückkehren zu lassen.", completion = "Ich sehe, dass Ihr einen Ast des Runenwalds bei Euch habt. Dann habt Ihr also dafür gesorgt, dass die Geister Ruhe finden?\n\nIch weiß zwar nicht, was Ihr vorhabt, Fremder, aber ich weiß zu würdigen, was Ihr für unsere Leute getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39792] = { id = 39792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordentlich was auf den Rippchen", description = "Während wir hier warten, könnt Ihr uns ja vielleicht was zum Essen besorgen. Die Tauren hatten zuletzt nicht mehr so viel Fleisch, deswegen wären sie wahrscheinlich dankbar, ein bisschen mehr davon zu bekommen.\n\nIch hab gehört, dass Moschusrippchen eine örtliche Spezialität sein sollen. Die wilden Moschushirsche auf dieser Seite des Flusses sind viel zu mager und bieten kein gutes Fleisch, aber auf der anderen Seite gibt es ein paar richtig fette Exemplare. Ihr solltet Euch dort mal umschauen!\n\nUnd keine Sorge: Ich bin mir ziemlich sicher, dass es da drüben keine Drachen gibt...", sourceObjective = "Sammelt 8 fleischige Moschusrippchen am Stück von den kräftigen Hochlandrunenhörnern im Jotunnwald.", progress = "Gibt doch nichts Besseres als ein paar gute alte Moschusrippen, oder?", completion = "Oh, hey... Ihr seid ja... wieder da! Offensichtlich habt Ihr mit diesen Moschushirschen keine Probleme gehabt. Ihr seid ja schließlich ein großer starker Jäger!\n\nDie Tauren sind aber immer noch nicht zurück. Ich mache mir ein bisschen Sorgen, dass sie sich bei der Jagd etwas zu viel zugemutet haben.\n\nOh, aber diese Rippchen nehme ich gern. Was wollt Ihr dafür haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[39793] = { id = 39793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur vom Feinsten", description = "Ihr seid doch <ein ziemlich guter Jäger/eine ziemlich gute Jägerin>, oder? Vielleicht könnt Ihr ja den Tauren helfen, indem Ihr ein paar seltene Felle erbeutet. Das werden sie sicher zu würdigen wissen, wenn sie zurück sind!\n\nIch hab gehört, dass man mit dem Ziegenhaar aus Sturmheim alles Mögliche anstellen kann. Die seltensten Tiere hier sind die Silberschwanzbergziegen. Und ich glaube, ich hab ein paar davon in den Bergen da drüben gesehen.\n\nWollt Ihr nicht einige von ihnen erlegen? Ich wette, die Tauren zahlen Euch einen guten Preis dafür!", sourceObjective = "Sammelt 18 Büschel feinstes Ziegenhaar von den Silberschwanzbergziegen in Nastrondir.", progress = "Und nehmt nur das Beste!", completion = "Ihr seid zurück? \n\nIch meine... He, Ihr seid zurück!\n\nNun, die Tauren sind immer noch nicht wieder da. Aber keine Sorge, ich nehme Euch das gute Zeug ab! Ich zeige Euch mal ein paar meiner schönsten Waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39794] = { id = 39794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Maxwell Tyrosus Slotted" }
quests[39795] = { id = 39795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindicator Boros Slotted" }
quests[39796] = { id = 39796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Haustvald", description = "Eure nächsten Schritte sind eindeutig. Eure Füße kennen den Weg. Folgt ihnen nach Haustvald, um Euch dort Eurem Schicksal zu stellen!\n\nEs ist ein Baum, nach dem Ihr sucht, das Herz des mystischen Runenwalds. Er wird Rat für Euch haben... und womöglich ein paar Blätter.", sourceObjective = "Trefft Euch mit Vydhar im Runenwald.", completion = "Gebunden... verderbt...\n\nDie Knochensprecher...", sourceObjectiveStatus = "unverified-source-field" }
quests[39797] = { id = 39797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aponi Brightmane Slotted" }
quests[39798] = { id = 39798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Liadrin Slotted" }
quests[39799] = { id = 39799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser nächster Schritt", description = "Habt Ihr den Nebel bemerkt, der uns umgibt? Die kühlen Winde von Acherus geben uns die Gelegenheit, uns optimal vor den neugierigen Augen der Legion zu verbergen!\n\nUnter dem Schleier dieses Nebels konnten wir Kundschafter aussenden, die eine recht ausführliche Karte der Verheerten Inseln zusammengestellt haben.\n\nWählt, wo wir mit dem Angriff beginnen sollen. Natürlich wird Euch die Ehre zuteil, unser Vorhaben anzuführen, doch der Rest der Schwarzen Klinge wird gleich hinter Euch stehen.", sourceObjective = "Wählt den ersten Angriffspunkt Eures Ordens.", completion = "Eine gute Wahl, Todesgebieter.", sourceObjectiveStatus = "unverified-source-field" }
quests[39800] = { id = 39800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graumähnes Schachzug", description = "Die Himmelsfeuer ist für die Reise nach Sturmheim bereit. Falls es zum Gefecht kommt, brauche ich meine besten Kämpfer an der Front.\n\nDazu zähle ich auch Euch, {class}.", sourceObjective = "Schließt Graumähnes Mission an Bord der Himmelsfeuer ab.", completion = "Anscheinend seid Ihr von der Wucht der Explosion verschont geblieben. Wenn doch nur Graumähne ebenfalls ein solches Glück gehabt hätte...\n\nAuf die Beine! Wir müssen fort, bevor die Verlassenen uns überwältigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39801] = { id = 39801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zersplitterte Flotte", description = "Die Vorbereitungen wurden getroffen und wir sind bereit, die Segel zu setzen.\n\nWir müssen sofort zuschlagen. Trödelt nicht, sonst bleibt Ihr zurück.", sourceObjective = "Schließt Sylvanas' Mission ab, um die Flotte nach Sturmheim zu bringen.", completion = "He, Ihr seid noch am Leben! Welk ist wohl doch nicht so verrückt, wie ich dachte.\n\nEs ist ein Wunder, dass Ihr der Himmelsfeuer lebendig entkommen konntet! Nach dieser Explosion müssen ihre Einzelteile im ganzen Gebirge verstreut sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[39802] = { id = 39802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hartli the Snatcher" }
quests[39803] = { id = 39803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfungen gehen weiter", description = "<Havis Stimme hallt erneut durch Euren Kopf, während der Rabe Euch weiter anstarrt.>\n\nUm Mut zu finden, müsst Ihr Zwiesprache mit den Knochen halten!\n\nDoch zuvor müsst Ihr Euch vorbereiten!", sourceObjective = "Trefft Euch mit Havi in Valdisdall.", completion = "Ah, der Held der Stunde! Wir dürfen keine Zeit verschwenden!\n\nUnsere aktuellen Angelegenheiten sind jetzt von höchster Bedeutung, wenn Ihr die Prüfungen bestehen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[39804] = { id = 39804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo wir von Knochen sprechen...", description = "Die Prüfung der Tapferkeit wird Eure nächste Aufgabe sein. Und das wird nicht leicht!\n\nAber nur Narren kämpfen mit leerem Magen. Seid Ihr etwa <ein Narr/eine Närrin>, <Fremder/Fremde>?\n\nNein? Dann geht einem alten Greis zur Hand und schlachtet diesen Elch für unser Mahl. Und ich werde Euch eine Geschichte erzählen, von Felsen, Bäumen und Geistern.", sourceObjective = "Helft Havi, den Elch zu schlachten, und erfahrt mehr über Eure nächste Prüfung.", completion = "Ausgezeichnete Arbeit.\n\nJa, ich glaube, Ihr werdet gegen die Knochensprecher bestehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[39805] = { id = 39805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drogbar Spellcaster" }
quests[39806] = { id = 39806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crawshuk the Hungry" }
quests[39807] = { id = 39807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Snowbringer" }
quests[39812] = { id = 39812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Weißwasserschnellen" }
quests[39816] = { id = 39816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thassarian", description = "<Todesgebieter/Todesgebieterin>, ich habe unseren verlorenen Ritter gefunden. Er begehrt, zur Schwarzen Klinge zurückkehren, und möchte unbedingt selbst mit Euch sprechen.\n\n<Mograine dreht sich und nickt einer nahen Wache zu.>\n\nEr müsste gleich hier sein.", sourceObjective = "Heißt Euren neuen Ritter willkommen.", completion = "Wir haben gemeinsam viel durchgemacht, {name}. Jetzt steht Ihr als Todesgebieter und Anführer unseres Ordens vor mir. Ich platze fast vor Stolz!\n\nDer Kampf gegen die Brennende Legion wird hart und gefährlich sein. Ihr solltet ihn nicht alleine aufnehmen.\n\nIch werde auf Euer Geheiß überall hingehen und töten, wen immer ich für Euch töten soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[39817] = { id = 39817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Schwefels", description = "Während Ihr die Dinge für mich gesammelt habt, um die ich Euch gebeten hatte, habe ich ein paar Tests mit dem Schwefel unternommen. Auf Kanalisierung hat er sehr heftig reagiert. Die Kreatur, von der diese Probe stammt, wurde mithilfe sehr behutsamer Magie erschaffen.\n\nSofern Ihr keine Armee dämonischer Zauberwirker zur Verfügung habt, ist die Nachbildung einer solchen Kreatur unmöglich.\n\nDas ist alles, was ich Euch zu sagen habe. Und jetzt geht und lasst mich in Ruhe, bevor der Hunger mich überkommt.", sourceObjective = "Erzählt Mama Buddel, was Ihr von Matthew erfahren habt.", completion = "Verstehe. Also, ein wenig hilft uns das schon weiter.\n\nMit diesen Informationen im Hinterkopf können wir mit unserer Erforschung dieser Ressource fortfahren, denke ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[39818] = { id = 39818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nazgrim", description = "<Todesgebieter/Todesgebieterin>, ich habe unseren verlorenen Ritter gefunden. Er begehrt, zur Schwarzen Klinge zurückkehren, und möchte unbedingt selbst mit Euch sprechen.\n\n<Mograine dreht sich und nickt einer nahen Wache zu.>\n\nEr müsste gleich hier sein.", sourceObjective = "Heißt Euren neuen Ritter willkommen.", completion = "Diese dummen Klassenausbilder reden immer mit mir, als ob ich noch nie eine Axt in der Hand gehalten hätte!\n\nSie können mir nichts Neues mehr beibringen. Die dunkle Macht der Untoten durchströmt meine Adern und strebt nach Blut und Kampf!\n\nWir sollten keine weitere Zeit in dieser staubigen Nekropole vergeuden! Schickt mich an die Front, damit ich das Blut unserer Feinde vergießen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[39824] = { id = 39824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 025 - Skyhorn Waterfall" }
quests[39828] = { id = 39828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horseman and Guards Shared Criteria" }
quests[39829] = { id = 39829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleigh and Guards Shared Criteria" }
quests[39830] = { id = 39830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerzitadelle: Höllenfeuer und Schwefel", description = "Als Khadgars Gruppe die Höllenfeuerzitadelle stürmte, mussten sie vielen dämonischen Kommandanten entgegentreten, doch keiner davon war so mächtig wie Archimonde selbst.\n\nVielleicht birgt seine Leiche etwas hilfreiches, um das Geheimnis des lebenden Schwefels endgültig zu lüften.", sourceObjective = "Stürmt gemeinsam mit Euren Mitstreitern die Höllenfeuerzitadelle. Besiegt dort Archimonde und entwendet ihm den Höllenkodex.", progress = "Geht nicht allein. An diesem Ort wimmelt es von Dämonen.", completion = "Ihr habt tatsächlich etwas gefunden?!\n\n<Mama Buddel analysiert mit ernster Mine den Kodex Seite für Seite.>\n\nAh, da ist es. Diese Seiten bergen alle Antworten...", sourceObjectiveStatus = "unverified-source-field" }
quests[39832] = { id = 39832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pläne und Vorbereitungen", description = "Eure Waffe ist stärker denn je, doch muss sie noch viele Seelen sammeln, bevor sie ihr wahres Potenzial erreicht.\n\nSiouxsie hat Berichte von den Spähern gesammelt und wird Euch den Weg zu unseren Feinden weisen. Dann können ihre schreienden Seelen Eurer Waffe mehr Macht verleihen.", sourceObjective = "Sprecht mit Siouxsie der Banshee.", completion = "Todesgebieter, ich habe einen kurzen Bericht über all unsere Entdeckungen in diesen neuen Landen zusammengefasst.\n\nIhr werdet ihn sicher interessant finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39837] = { id = 39837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unwürdige Aufgabe", description = "Das hier ist Helheim, das Reich der unwürdigen Toten. Hier kämpfen die Geister der Ehrlosen einen ewigen Kampf, stets auf der Suche nach Ruhm, doch nie in der Lage, ihn zu erlangen.\n\nWir sollten nicht hier sein.\n\nWir müssen einen Weg zurück finden. Ich werde mich umsehen. Ihr solltet versuchen, ein paar dieser gefangenen Geister zu befreien. Vielleicht können sie uns ja weiterhelfen.", sourceObjective = "Sucht unter den gefangenen Vrykul in Helheim nach einem, der Euch bei der Flucht behilflich sein kann.", completion = "Endlich frei!\n\nDie Kvaldir haben mich erwischt, als ich einen Plan entwickelte, um an diesem Höllenhund, Guarm, vorbeizukommen. Und seitdem war ich eingesperrt!\n\nIch dachte schon, dass mein Schicksal besiegelt sei.", sourceObjectiveStatus = "unverified-source-field" }
quests[39838] = { id = 39838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer!", description = "Ihr da! <Abenteurer/Abenteurerin>! Packt hier mit an! Der Wagen hat Feuer gefangen!", sourceObjective = "Nutzt Camille Kleisters Wassereimer, um das Feuer zu löschen.", progress = "Warum steht Ihr nur herum und haltet Maulaffen feil! Macht Euch nützlich!", completion = "Das war... unerwartet. Teufelsflammen? Ich würde sagen, das verlangt nach einer näheren Untersuchung.", sourceObjectiveStatus = "unverified-source-field" }
quests[39839] = { id = 39839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvoller Staub", description = "Beinahe der gesamte Wageninhalt wurde vom Feuer zerstört. Nur ein kleiner Haufen Staub ist übrig geblieben.\n\nDieser Wagen gehörte Händler Caelen. Vielleicht weiß er mehr darüber, was passiert ist.\n\nWas den Staub betrifft, vielleicht können die Inschriftenkunde- oder Alchemielehrer mehr Klarheit bringen.", sourceObjective = "Sprecht mit Händler Caelen, Professor Pallin und Deucus Valdera über den geheimnisvollen Staub.", completion = "Dieses Puder... Ich glaube zu wissen, was das ist. Ich hatte seine Existenz in der Theorie vorausgesagt, aber...\n\nHey, Vanessa! Kommt mal her und schaut Euch das an.", sourceObjectiveStatus = "unverified-source-field" }
quests[39840] = { id = 39840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zustimmung des Rats", description = "Die Ergebnisse waren durch und durch enttäuschend. Die Kalzinierung ist ein komplexer Vorgang, der besser von Alchemisten oder Schmieden durchgeführt wird. Trotzdem hätte ich gehofft, dass wir mehr als ZWEI MICKRIGE GRAN Obliterum erhalten.\n\nFür eine effizientere Reaktion benötigen wir eine spezielle Schmiede. Und um die zu erhalten...\n\n...müssen wir die Zustimmung des Rates der Sechs bekommen.", sourceObjective = "Sprecht mit Khadgar in Dalaran und erbittet seine Zustimmung, eine Obliterumschmiede zu bauen.", completion = "Ich mag, wie Ihr denkt, {race}. Ich versuche den Rat schon seit Langem zu überzeugen, dass wir, um den Krieg gegen die Legion zu gewinnen, uns manchmal auf ihr Niveau hinabbegeben müssen.\n\nDie Kirin Tor könnten mehr Freidenker wie Euch brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39841] = { id = 39841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde im Untergrund", description = "Meine Kontaktperson ist eine gewisse Oxana Dämonstod. Sie hat das Angebot abgelehnt, offiziell nach Dalaran zu kommen, und bevorzugt es stattdessen, sich in der Schattenseite aufzuhalten.\n\nWenn irgendjemand auf diesem Felsbrocken weiß, wie man eine funktionierende Obliterumschmiede baut, dann sie.\n\nOh, und passt auf Euch auf, während Ihr da unten seid, {name}.", sourceObjective = "Meldet Euch bei Oxana Dämonstod in der Schattenseite.", completion = "Der Erzmagier hat Euch geschickt? Hmpf.\n\nHatte er Angst, hier herunterzukommen und mich persönlich zu besuchen? Oder sorgt er sich darum, dass sein Robensaum durch das Abwasser schleifen könnte?", sourceObjectiveStatus = "unverified-source-field" }
quests[39842] = { id = 39842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Magiers Leid...", description = "Ich kann Euch helfen, Eure Schmiede zu bauen. Ich kann sogar das Metall beisteuern. Jedoch benötige ich einige... schwieriger zu beschaffende Komponenten.\n\nIch brauche eine alchemistische Wärmequelle, eine Art Isolierung und eine Heizung. Ich bin mir sicher, dass all das hier in der Schattenseite aufgetrieben werden kann... wenn die Wachen gerade nicht hinsehen.", sourceObjective = "Findet eine Phiole mit alchemistischer Flamme, eine Rolle bezauberter Isolierung und eine stillgelegte Heizung.\n\nDiese Gegenstände können nur beschafft werden, wenn die Kanalwächter von Dalaran außer Dienst sind.", progress = "Lasst Euch nicht von diesen Wächtern erwischen. Sie sind zwar korrupt, aber sie sind wachsam.", completion = "Ich hoffe, es hat Euch keine Schwierigkeiten bereitet, diese Dinge aufzutreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[39843] = { id = 39843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herumschmutzen endet hier", description = "Für meinen nächsten Arbeitsschritt, die Komponenten der Schmiede zusammenzufügen, benötige ich einen magischen Klebstoff. Und ich habe herausgefunden, dass die angestaute Schlacke aus der Kanalisation von Dalaran geradezu perfekt dafür geeignet ist.\n\nSie setzt sich an den Füßen, Stiefeln und schlängelnden Bäuchen der langlebigeren Bewohner von Dalaran ab. Kratzt etwas davon ab und bringt sie her.", sourceObjective = "Beschafft 20 Phiolen Zauberschlacke.\n\nZauberschlacke kann bei den machtvolleren Kreaturen der Schattenseite gefunden werden, die erscheinen, wenn die Kanalwächter von Dalaran im Dienst sind.", progress = "Wenn Ihr in der Kanalisation lebt, müsst Ihr bereit sein zu improvisieren.", completion = "Machen wir keine große Sache draus. Ihr wolltet eine Schmiede... ich baue eine für Euch. Der Zweck heiligt die Mittel.", sourceObjectiveStatus = "unverified-source-field" }
quests[39844] = { id = 39844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnöder Mammon", description = "Ich bin nicht an Gold interessiert. Eure oberirdischen Währungen haben hier unten wenig Nutzen.\n\nIch bin jedoch an blinden Augen interessiert. Ich werde sie sehr gern als Bezahlung für meine Dienste annehmen.", sourceObjective = "Beschafft 100 blinde Augen.", progress = "Blinde Augen, {name}.", completion = "<Der Dämonenjäger nimmt die Münzen an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[39845] = { id = 39845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Obliterumschmiede", description = "Die Komponenten der Schmiede sind zusammengebaut, und soweit ich weiß, hat Erzmagier Karlain einen Platz für uns gesichert, damit wir mit der Konstruktion beginnen können: überirdisch, in der Nähe der Schmiede.\n\nKommt doch mal wieder vorbei, {name}.", sourceObjective = "Schließt die Konstruktion der Obliterumschmiede in Dalaran ab.", completion = "Sieh sich einer die Hörner an dem Ding an. Und diese glühenden Augen...\n\nDiese Dämonenjäger haben wirklich ein Gespür für Dramatik, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[39846] = { id = 39846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Dalaran - Treasure 001 - Burnt Cart" }
quests[39847] = { id = 39847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterschreibt dies", description = "Ah, <ein Schreiberkollege/eine Schreiberkollegin>!\n\nIhr scheint mir recht helle zu sein, also warum arbeiten wir nicht zusammen daran, so viel wie möglich über die Verheerten Inseln herauszufinden?\n\n(Das ist der Inselhaufen, über dem wir gerade schweben.)\n\nEins nur: Ich stimme keiner Zusammenarbeit ohne die entsprechenden rechtlichen Formalitäten zu. Unterschreibt dies für mich, dann haben wir eine Vereinbarung.", sourceObjective = "Unterzeichnet Professor Pallins Vertrag.", progress = "Habt Ihr auch den Strich beim kleinen \"T\" und den Punkt beim kleinen \"J\" nicht vergessen?", completion = "Hey, Ihr könnt ja sogar Euren Namen fehlerfrei schreiben!\n\nDas nenne ich einen vielversprechenden Anfang!", sourceObjectiveStatus = "unverified-source-field" }
quests[39848] = { id = 39848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Bitte", description = "Euer Freund scheint es nicht geschafft zu haben. Das tut mir leid, aber wir müssen weiter.\n\nIhr solltet mit Helya sprechen. Sie ist hier die Herrscherin. Ich würde Euch ja begleiten, aber ich fürchte, das würde Eurem Anliegen nicht weiterhelfen.\n\nSucht mich auf, wenn Ihr fertig seid. Ich versuche herauszufinden, wo sich meine Schildmaiden aufhalten.", sourceObjective = "Sucht Helya auf und bittet sie, Euch aus Helheim zu entlassen.", progress = "<Die Luft steht still, während Ihr Euch nähert.>", completion = "<Helyas Stimme erfüllt die Luft, während Ihr aufsteht.>\n\nNiemand verlässt Helheim ohne meine Erlaubnis! Bietet mir Unterhaltung, dann lasse ich Euch vielleicht gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39849] = { id = 39849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dem Licht", description = "Helya glaubt wohl, dass ihre Herausforderung nicht zu bestehen ist. Wir werden ihr das Gegenteil beweisen.\n\nIch bin mir nicht sicher, wie sie es geschafft hat, aber irgendwie hat Helya Euch geschwächt. Ich habe Ähnliches bei meinen Schildmaiden erlebt, und nun werden sie von Helyas Dienern gefangen gehalten.\n\nAber ich weiß vielleicht eine Möglichkeit. Auf den Schiffen der Kvaldir befinden sich bestimmte Laternen, die an diesen Ort gebunden sind und der Navigation durch den Nebel dienen. Man sagt, dass das Licht dieser Laternen Fesseln des Geistes lösen kann.\n\nEs befindet sich ein Schiff der Kvaldir ganz in der Nähe. Vielleicht findet Ihr dort eine dieser Laternen.", sourceObjective = "Besorgt ein Weglicht aus Helheim von Blutbart.", progress = "Konntet Ihr die Laterne sichern?", completion = "Das scheint zu sein, was wir benötigen.\n\nUnd jetzt können wir uns auf den anstehenden Kampf vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39850] = { id = 39850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissen", description = "Ich vermute, dass wir mit der Kraft Eurer Waffe Geir besiegen können, aber momentan seid Ihr zu schwach für diesen Kampf. Wir müssen erst die fehlenden Teile Eures Geistes zurückgewinnen.\n\nHelya hat sie sicher über ihr ganzes Reich verstreut, um sie vor Euch zu verbergen. Solltet Ihr sie finden, dann leuchtet mit der Laterne darauf, um sie wieder freizusetzen.\n\nAber gebt gut auf Euch acht: Helya lässt Eure Geistfragmente ganz sicher bewachen.", sourceObjective = "Sucht das Fragment des Willens, das Fragment der Macht und das Fragment der Tapferkeit in Helheim und befreit sie.", progress = "Habt Ihr Eure Kraft wiedererlangt?", completion = "Ja, ich spüre, dass Eure Macht zurückgekehrt ist.\n\nHelya wird den Tag bedauern, an dem sie Euch herausgefordert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[39851] = { id = 39851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete im Tod", description = "Unsere Kräfte allein werden vielleicht nicht ausreichen, um dieses Ungetüm Geir zu besiegen. Zum Glück hat uns Faljar ein paar Verbündete nach Helheim geschickt.\n\nIch habe schon vor einer Weile ein paar vor ihnen entdeckt, wie sie von Helheims Elementarmächten gefoltert wurden. Man würde meinen, die Toten könnten nicht ertrinken, doch mit Helyas Macht ist auch dies möglich.\n\nIch konnte sie nicht befreien, aber da Ihr jetzt das Weglicht habt, könnte es Euch gelingen.\n\nSucht sie und befreit sie von ihren ewigen Qualen!", sourceObjective = "Befreit 8 ertrinkende Valkyra in Helheim.", completion = "Danke, dass Ihr meine Schildmaiden zu mir zurückgebracht habt.\n\nHeute habt Ihr nicht nur Verbündete gewonnen, sondern Euch auch meinen ewigen Dank verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[39853] = { id = 39853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Ewigkeit", description = "Jetzt gibt es keinen Grund mehr zu zögern. Es ist an der Zeit zuzuschlagen.\n\nWir werden dieses widerwärtige Ungetüm vernichten und dann unseren Preis bei Helya einfordern. Der Weg aus Helheim heraus liegt vor uns, <Fremder/Fremde>. \n\nMacht Euch bereit.", sourceObjective = "Besiegt Geir auf dem Ewigen Schlachtfeld in Helheim.", progress = "Zusammen können wir diesen Gegner besiegen.", completion = "Der Sieg ist unser. Jetzt müssen wir unsere Belohnung einfordern.\n\nHoffen wir, dass Helya sich an ihren Teil der Abmachung halten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[39855] = { id = 39855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leben als Preis", description = "Wir haben getan, was Helya von uns verlangt hat. Jetzt werden wir ja sehen, ob sie Wort hält.\n\nWenn Ihr bereit seid, machen wir uns auf den Weg zum Thron. Wenn Ihr hier noch etwas zu erledigen habt, solltet Ihr das jetzt tun.\n\nGeht Ihr voran, <Fremder/Fremde>.", sourceObjective = "Sucht Helya auf und verlasst Helheim.", completion = "Die Toten finden also ihren Weg zurück aus Helheim? Eine beeindruckende Leistung.\n\nIhr habt Euch als würdig erwiesen und die Prüfung bestanden.\n\nUnd jetzt stellt Euch Eurem Schicksal. Auf zu den Hallen der Tapferkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[39856] = { id = 39856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Wraithtalon" }
quests[39857] = { id = 39857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ewige Widersacher", description = "<Helyas Stimme hallt durch den Himmel über dem Altar.>\n\nIhr behauptet, Ihr gehört nicht hierher zu den Unwürdigen, <Fremder/Fremde>, doch Euer Geist zerfällt wie Sand. Wie kann ich wissen, dass Ihr die Wahrheit sprecht?\n\nGar nicht! Daher werdet Ihr es beweisen.\n\nBegebt Euch zum Ewigen Schlachtfeld und stellt Euch meinem Champion. Wenn Ihr ihn besiegen könnt, will ich Euch Gnade gewähren.", sourceObjective = "Kehrt zu Ashildir zurück und erzählt ihr von Helyas Herausforderung.", completion = "Ihr seht gar nicht gut aus.\n\nDann hat sich Helya also nicht einsichtig gezeigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[39858] = { id = 39858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dreadbog" }
quests[39859] = { id = 39859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziegen, die Notizen fressen", description = "Ich bin Hemet auf all seinen Reisen vom Schlingendorntal bis nach Nagrand und... wieder nach Nagrand gefolgt, habe Notizen über seine großen Abenteuer verfasst und sie in zeitlose literarische Werke verwandelt.\n\nAber mein Herz schlägt eigentlich ganz für die Jagd. Nichts wäre mir lieber, als die Schreibfeder niederzulegen und selbst ein Gewehr in die Hand zu nehmen.\n\nHemet hat versprochen, mir das Jagen beizubringen, sobald ich den neuesten Roman fertiggestellt habe – doch die Ziegen hier haben meinen ersten Entwurf gefressen!\n\nEs gibt keine Hoffnung darauf, eine Jägerin zu werden, wenn ich das Manuskript nicht wiederfinde.", sourceObjective = "Beschafft Addies Manuskriptseiten von den vollgefressenen Hügelschreitern im Kieferfelsbecken zurück.", progress = "Ich habe den ganzen Tag darauf gewartet, dass Addie ihren ersten Entwurf fertigstellt.\n\nWie schwer kann es schon sein, ein paar Worte über den größten Jäger zu verfassen, den die Welt je gesehen hat?", completion = "Ich wollte dieses Manuskript unbedingt in die Hände bekommen! Dachte schon, diese Gnomin hätte eine Schreibblockade.", sourceObjectiveStatus = "unverified-source-field" }
quests[39860] = { id = 39860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus des Blutes", description = "Oakin Eisenstier bürgt für Euch. Er ist brauchbar, für eine Flussmähne. Ihr habt auch einen Beweis Eurer eigenen Stärke mitgebracht, auch wenn er etwas dürftig ist.\n\nBevor wir Euch freies Geleit durch unser Territorium gestatten, müsst Ihr den Ritus des Blutes abschließen, den Ihr bereits begonnen habt. Wenn Ihr erfolgreich seid – was ich bezweifle –, dann sprecht wieder mit mir.\n\nBetretet die Tiefen der Höhle. Bezwingt jeden Gegner, der sich Euch entgegenstellen mag, und kehrt dann zu mir zurück.", sourceObjective = "Schließt den Ritus des Blutes ab.", progress = "Fürchtet Ihr die Dunkelheit?", completion = "Danke, dass Ihr mich gerettet habt. Ich hoffe, wir können einander nun trauen. Wenn wir die Teufelstotems bezwingen wollen, müssen wir dazu bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[39861] = { id = 39861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn alles zusammenkommt", description = "Malfurion Sturmgrimm ist es gelungen, in Val'sharah an Land zu gehen. Und er hat dort auch bereits das Kommando übernommen. Endlich scheint sich das Glück uns zuzuwenden!\n\nEr wartet zur Stunde auf Euch in Lorlathil. Das Leben fühlt sich magisch an, wenn alles nach Plan verläuft.", sourceObjective = "Sprecht mit Aludane Wolkenweiß bei Krasus' Landeplatz, um Euch einen Flug nach Val'sharah zu sichern. Sprecht mit Malfurion Sturmgrimm, sobald Ihr in Lorlathil angekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[39862] = { id = 39862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Belagerungsbrul", description = "Würmer mögen weder Kämpfe noch die Oberfläche. Sie begeben sich nur dorthin, wohin ihr Meister es ihnen befiehlt.\n\nWenn man sich also im Krieg befindet, sollte man zuerst den Meister töten.\n\nBelagerungsbrul Olgrul ist der Wurmmeister der Machtsteindrogbar, die uns vom Norden her angreifen.\n\nTötet ihn.", sourceObjective = "Tötet Belagerungsbrul Olgrul.", completion = "\"Belagerungsbrul\". Pah!\n\nVor diesem Krieg hatten wir keine Verwendung für derartige Titel.\n\nOlgrul war immer nur ein Schläger, der Spaß daran hatte, anderen Schmerzen zuzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39863] = { id = 39863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsfeuerprobe", description = "Die Substanz, die Ihr da habt, ist etwas, das sich \"Obliterum\" nennt. Wir hatten ihre Existenz theoretisch beschrieben, aber bis jetzt waren wir nicht in der Lage, etwas davon zu erzeugen.\n\nIhr sagt, das stammt aus einem Brand? Aber NATÜRLICH! Erhitzung! Warum bin ich nicht früher darauf gekommen?\n\nWir müssen aber zunächst die Ergebnisse reproduzieren, bevor wir weitere Schritte einleiten. Ich weiß, es ist eine große Bitte, aber Ihr müsst mir zunächst einige hochwertige Rüstungsteile verschiedener Arten bringen.", sourceObjective = "Beschafft je einen Satz machtgetränkter seidengewebter Armschienen, Schreckenslederbindungen, Gravurschuppenarmbinden und Dämonenstahlarmschützer.", progress = "Ihr braucht kein Geld auf teure Brustplatten oder Roben zu verschwenden. Ein paar einfache Armschienen werden den Zweck erfüllen.", completion = "Ihr habt die Armschienen? Sehr gut, und nun tretet zurück...", sourceObjectiveStatus = "unverified-source-field" }
quests[39864] = { id = 39864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmheim", description = "Nathanos Pestrufer, der Champion der Bansheekönigin höchstpersönlich, will, dass Ihr nach Dalaran kommt.\n\nEr erwartet Euch in der Violetten Zitadelle. Es klang dringend.", sourceObjective = "Sprecht mit Nathanos Pestrufer in der Violetten Zitadelle in Dalaran.", completion = "<Nathanos schaut Euch kurz an und hält dann inne, bevor er Eure Anwesenheit zur Kenntnis nimmt.>\n\nJa?", sourceObjectiveStatus = "unverified-source-field" }
quests[39865] = { id = 39865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Scarecrow Costume" }
quests[39866] = { id = 39866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scout Harefoot" }
quests[39867] = { id = 39867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin doch nicht blind!", description = "Ich hab in meinem Leben schon viele exotische Tiere gejagt. Aber so ein Löwe, wie ich ihn auf meiner Erkundung des Beckens gesehen habe, ist mir noch nie begegnet.\n\nDie bernsteinfarbenen Augen der Bestie haben sich in meine gebohrt und mich geradezu zu ihm hingezogen. Ich war dem Blick des Raubtiers hilflos ausgeliefert. Erst als der Löwe lossprang, löste sich dieser Bann.\n\nIch habe Hemet von dieser magischen Raubkatze erzählt, aber er hat mich nur ausgelacht. Ich lüge nicht, {name}! Dieser Löwe existiert.\n\nWenn Ihr die Raubkatze finden und töten könnt und mir eine Trophäe mitbringt, werde ich Euch großzügig entlohnen.", sourceObjective = "Erbeutet eine Jagdtrophäe von dem Löwen, den Ellias im Kieferfelsbecken gesehen haben will.", progress = "Wenn Hemet den Beweis für die Existenz des magischen Löwen sieht, werde ich zuletzt lachen.", completion = "Ich hatte also recht! Der Löwe mit den bernsteinfarbenen Augen hat existiert.\n\nHier ist das versprochene Gold. Das war es mir wert. Am Ende recht zu behalten, ist mir jeden Preis wert!\n\nIch werde dieses Auge behalten, aber ich möchte den Rest unserer Beute nicht verschwenden. Lasst uns essen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39869] = { id = 39869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenzoll", sourceObjective = "Besiegt Helya und befreit die Valarjar.", sourceObjectiveStatus = "unverified-source-field" }
quests[39870] = { id = 39870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Soulthirster" }
quests[39871] = { id = 39871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huntress Ellandryn" }
quests[39872] = { id = 39872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beastly Boxer" }
quests[39873] = { id = 39873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mir ist nicht wohl bei der Sache", description = "Ihr habt guten Grund, mir nicht zu vertrauen. Meine von Dargrul angeführten Cousins wurden von Machtgelüsten in den Wahnsinn getrieben.\n\nAber ich möchte, dass Ihr ein paar Nachforschungen anstellt. Ich habe das Gefühl, dass Hochberg ein schreckliches Unheil droht und Torok und sein Bluttotemstamm dafür verantwortlich sind.\n\nWenn Ihr mir nicht glaubt, dann überzeugt Euch an der Nordseite des Klippenrands selbst.", sourceObjective = "Untersucht Navarroggs finstere Vermutungen.", completion = "<Der Käfig ist leer. Navarrogg ist nicht mehr da.>", sourceObjectiveStatus = "unverified-source-field" }
quests[39874] = { id = 39874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zauberhafter Abend", description = "Willkommen! Es ist immer eine Freude, wenn jemand Vertrautes nach Dalaran zurückkehrt. Ihr kennt Ildine, Vanessa und mich vielleicht noch aus Nordend.\n\nErzmagier Sternensinger leitet den Laden, aber er ist gerade unterwegs, um Geschäfte mit den Kirin Tor zu machen. Er ist wirklich ein guter Mann... meistens.\n\nIhr kommt gerade richtig, denn es gibt da ein Problem, das wir lösen wollen, bevor der Erzmagier zurück ist. Seid Ihr interessiert?", sourceObjective = "Sprecht mit Ildine Sorgenspeer im Zauberladen in Dalaran.", completion = "Ich bin sehr erleichtert, dass Ihr kommen konntet, {name}. In Zeiten wie diesen können wir ganz sicher noch einen Verzauberer in unserem Laden brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39875] = { id = 39875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Vorbereitungen", description = "{name}, wie Ihr seht, stellen wir unablässig neue Verzauberungen für den Kampf gegen die Legion her. Da Ihr gerade da seid, könntet Ihr uns ja helfen, eine unserer Bestellungen fertig zu machen.\n\nIch möchte Euch bitten, ein paar Pergamente zu besorgen und sie mit Vielseitigkeit zu verzaubern. Hier, ich zeige Euch die Formel.", sourceObjective = "Stellt im Auftrag von Ildine 2 Pergamente für einen Ring - Wort der Vielseitigkeit her. Pergamente könnt Ihr von einem Schreiber oder im Auktionshaus erwerben.", progress = "Seid Ihr mit dem Verzaubern der Pergamente schon fertig?", completion = "<Ihr überreicht Ildine die Pergamente.>\n\nSo, das waren die letzten. Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[39876] = { id = 39876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Jäger", description = "Während ich den Rest unserer Aufträge ausführe, wäre ich Euch sehr zu Dank verpflichtet, wenn Ihr diese Pergamente zu Jace Düsterweber in Azsuna bringen könntet.\n\nEr und die anderen Dämonenjäger halten die Legion jetzt schon eine ganze Weile in Schach und könnten sie so schnell wie möglich brauchen.\n\nDanke, {name}!", sourceObjective = "Bringt die Kiste voller Pergamente zu Jace Düsterweber in Azsuna.\n\nBereitgestellter Gegenstand:", completion = "<Jace nimmt Euch die Kiste ab und späht hinein.>\n\nDie Pergamente! Endlich sind sie hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[39877] = { id = 39877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer in Bewegung bleiben", description = "Wir könnten Eure Hilfe hier unten brauchen, {name}. Einige unserer Jäger würden sehr davon profitieren, wenn ihre Ringe jetzt gleich mit diesen Pergamenten verzaubert würden.\n\nHier, nehmt ein paar. Den Rest gebe ich meinen anderen Soldaten, damit die sie austeilen können.\n\nMeine Jäger werden sich wahrscheinlich nicht durch die Verzauberungen aufhalten lassen wollen. Ihr werdet das also unter Umständen mitten im Kampf vornehmen müssen.", sourceObjective = "Wendet die Verzauberungspergamente auf 6 Dämonenjäger beim Verteidigungsposten der Illidari an.", completion = "Dadurch werden wir diese Dämonen sicher noch viel länger in Schach halten können. Wir stehen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39878] = { id = 39878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Donner gerührt", description = "Ich habe auf dem Hochberg eine potenzielle Quelle für neue Verzauberungen gefunden. Die Tauren am Donnertotem befehligen Geister, um Gegenstände mit großer Macht zu versehen.\n\nSucht einen Verzauberer namens Zweischwanz auf, und findet heraus, ob er sein Wissen mit uns teilen will.\n\nTauren teilen doch gerne, oder?", sourceObjective = "Sprecht mit Guron Zweischwanz in Donnertotem.", completion = "Die Geister haben mir gesagt, dass Ihr kommen würdet, Fremder. Wir werden sehen, ob Ihr wirklich der Held seid, den das Land so dringend braucht.\n\n<Der Tauren räuspert sich.>\n\nVergebt mir. Ich weiß, dass ich ein wenig melodramatisch klinge, aber diese Dinge sind mir wichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[39879] = { id = 39879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Kräfte", description = "Es gibt zwei Arten Geister in dieser Welt, {name}. Manche sind gutmütig, manche aggressiv.\n\nSie alle reagieren auf verschiedene Reagenzien, mit denen wir unsere Rüstungen verzaubern können. Zu diesen Reagenzien zählen unter anderem Kristalle von Bernsteinsplittern.\n\nDas sind gewalttätige Wesen, aus der Erde geboren. Sie wurden kürzlich von den Drogbar aufgescheucht. Allerdings bergen ihre Kristalle großen Nutzen für die Verzauberungen meines Volkes. Bringt mir ein paar davon, dann werde ich es Euch zeigen.", sourceObjective = "Besiegt wütende Bernsteinsplitter und sammelt \n8 ihrer Bernsteinkristalle ein. Bringt sie dann zurück zu Guron in Donnertotem.", progress = "Kristalle sind nicht das Einzige, auf das die Geister reagieren. Es gibt noch andere Dinge, aber darüber sprechen wir dann ein anderes Mal.", completion = "Die sind für meine Erklärungen perfekt.\n\n<Guron beginnt zu erklären, wie man mit den Geistern spricht und wie sie und der Kristall gegenseitig aufeinander einwirken.>\n\nVielleicht seid Ihr auch schon auf eine andere Kristallart gestoßen, den \"Leylichtsplitter\". Er funktioniert ähnlich, reagiert aber auf andere Geister.", sourceObjectiveStatus = "unverified-source-field" }
quests[39880] = { id = 39880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts verschwenden", description = "Wenn Ihr gegen die Bernsteinsplitter kämpft, um ihnen die Kristalle abzunehmen, stoßt Ihr vielleicht auf verzauberte Rüstungen unserer gefallenen Kriegerhelden. Den Bernsteinsplittern sind sie egal, aber unser Volk missbilligt die Verschwendung.\n\nIch möchte, dass Ihr die Rüstungen unserer Kriegerhelden bergt und sie entzaubert und damit wieder in ihre Komponenten zerlegt.\n\nBringt mir dann die Reagenzien zurück, damit wir damit neue Rüstungen verzaubern können.", sourceObjective = "Begebt Euch zur Kristallkluft und sucht nach zurückgelassenen Rüstungen. Entzaubert die Rüstungen und bringt Guron dann 15 Einheiten Donnerstaub.", progress = "Wenn wir verschwenden, was uns gegeben wurde, missachten wir die Geister, die es uns gegeben haben.", completion = "Eure Taten erweisen unserem Stamm Ehre. Ich werde dafür sorgen, dass der Staub gute Verwendung findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[39881] = { id = 39881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feenverzauberungen", description = "Der neue Staub und die Kristalle, die wir in diesem Land gefunden haben, sind faszinierend, wie Ihr bestimmt schon erahnt habt. Ich bin mir sicher, dass wir ihre Nützlichkeit auf weitere Rüstungsteile ausdehnen können.\n\nIch möchte, dass Ihr wieder loszieht und mit einer Dryade in Val'sharah sprecht. Offenbar kann sie uns Hinweise auf Verzauberungen für Schulterstücke geben.\n\nSie heißt Nalamya. Ihr findet sie in der Nähe des Tempels von Elune.", sourceObjective = "Sucht Nalamya in der Nähe des Tempels von Elune in Val'sharah auf.", completion = "Was wollt Ihr, {race}?\n\n\n\nAh, ich verstehe. Ihr seid ein Verzauberer.\n\nIch warne Euch allerdings: Wenn Ihr meine Verzauberungen nehmt und sie wie diese widerwärtigen Elfen von der Rabenwehr für böse Zwecke benutzt, werdet Ihr auf die eine oder andere Weise meinen Zorn zu spüren bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39882] = { id = 39882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Freundschaft gekündigt", description = "Ich habe den Nachtelfen einst beigebracht, wie sie ihre Rüstungen verzaubern können, um sich gegen die bösen Mächte dieses Landes zur Wehr zu setzen. Einen der Elfen habe ich besonders gefördert.\n\nEs ist Erzdruide Glaidalis. Er lebt jetzt in dem Wald, den man als das Finsterherzdickicht kennt, und schmiedet Pläne, um unsere Welt mit dieser fürchterlichen Seuche zu vernichten.\n\nVor seinem Verrat hatte ich ihm zu Studienzwecken mein Buch der Verzauberungen überlassen, und ich möchte es unbedingt zurückhaben.\n\nIch vertraue Euch diese Aufgabe an, <Verzauberer/Verzauberin>. Bringt mir mein Buch zurück.", sourceObjective = "Tötet den Erzdruiden Glaidalis im Finsterherzdickicht und holt Nalamyas Buch der Verzauberungen zurück.", progress = "Wenn Ihr in diesem Krieg auf unserer Seite steht, dann kämpft für mich und besiegt Glaidalis.", completion = "Ihr habt es? Und Glaidalis ist auch tot?\n\nIch bin zwar erleichtert, dass dieser mächtige Feind beseitigt wurde, aber ich trauere dennoch um die vergebenen Möglichkeiten...\n\nAuf jeden Fall habt Ihr aber bewiesen, dass Ihr ein Verbündeter seid. Zur Belohnung werde ich Euch eine meiner Verzauberungen lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39883] = { id = 39883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haufenweise Tradition", description = "Ihr habt die Lebensweise der Tauren von Donnertotem kennengelernt... wie wir mit den Geistern sprechen, die Ressourcen des Landes nutzen und nichts verschwenden. Dies sind die ausschlaggebenden Kräfte für Eure Mission auf den Verheerten Inseln.\n\nHier, bringt dieses Tagebuch Eurem Verzaubererfreund. Es enthält die Lektionen, die ich Euch gelehrt habe.\n\nVielleicht sind Euch diese Dinge von Nutzen, um die Legion zu besiegen.", sourceObjective = "Bringt Gurons Tagebuch zu Nalthanis in Dalaran.", progress = "Willkommen zurück, {name}. Habt Ihr Kontakt mit den Tauren gehabt?", completion = "Wie ich sehe, habt Ihr ein Geschenk vom Hochberg mitgebracht.\n\n<Nalthanis blättert durch die Seiten.>\n\nFaszinierend! Schaut her, {name}, ein paar Formeln für Umhangverzauberungen. Ich glaube, die können wir gerade jetzt sehr gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39884] = { id = 39884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr würdig", description = "Die Elfen der Rabenwehr haben uns im Stich gelassen. Sie verschanzen sich in ihrer Festung und verteidigen sie lediglich gegen Eindringlinge.\n\nDerartiges Verhalten ist unentschuldbar... insbesondere nachdem sie von meinem und anderen Völkern dieses Landes so viel Hilfe erhalten haben.\n\nIch möchte Euch um einen Gefallen bitten, {name}. Nehmt ihnen ihre verzauberten Siegel ab und zermalmt sie zu Staub. Bringt mir dann den Staub als Beweis zurück.", sourceObjective = "Tötet Nachtelfen in der Rabenwehr und nehmt ihnen ihre verzauberten Rabensiegel ab. Entzaubert die Siegel und bringt dann zum Beweis 8 Einheiten Rabenstaub zurück zu Nalamya.", progress = "Ihr Verhalten war so seltsam und so unvermittelt. Ich weiß nicht, warum sie weggerannt sind. Aber das ist nicht entschuldbar.", completion = "<Nalamya nimmt den Staub von Euch entgegen.>\n\nGut gemacht, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39889] = { id = 39889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlgeleitet", description = "Die Nachtelfen sind keine Narren, aber die Elfen der Rabenwehr folgen ihren Kommandanten in blindem Gehorsam. Ich bin mir sicher, dass diese Kommandanten für ihre Trägheit verantwortlich sind.\n\nIch kenne zwei dieser Anführer. Sie weigern sich, ihre Truppen in den Kampf gegen die Seuche zu führen, die meine Heimat bedroht.\n\nBegebt Euch zur Rabenwehr und tötet Trelan Schildbrecher und Starlys Starkbogen. Setzt ein Zeichen und macht deutlich, was passiert, wenn man sich feige verbirgt, anstatt zu helfen.", sourceObjective = "Begebt Euch zur Rabenwehr in Val'sharah und tötet Trelan Schildbrecher und Starlys Starkbogen.", completion = "Macht Euch keine Mühe mit Beweisen. Ich habe überall meine Augen und Ohren, die mir von Euren Taten berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39891] = { id = 39891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflucht, aber zweckmäßig", description = "Ihr müsst sofort für mich nach Azsuna zurückkehren, {name}. Ich habe gerade erst von einer Verzauberin im Zerfallenen Palast erfahren, die viele seltene Verzauberungen kennt.\n\nGeht auf der Stelle zu ihr und seht, was Ihr von ihr lernen könnt.", sourceObjective = "Sucht Verzauberin Ilanya im Zerfallenen Palast in Azsuna auf.", completion = "Ah, ein Verzauberungskollege. Seid Ihr hergekommen, um Euch die Male meiner Untergebenen zu verdienen?\n\nWenn ja, dann dürft Ihr mit meiner Schildwache und meinem Druiden sprechen. Verdient Euch ihr Vertrauen und sie werden Euch ihre Male überlassen.\n\nIch allerdings habe eine andere Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[39903] = { id = 39903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bezauberndes Zuhause", description = "Je mehr ich über die Verheerten Inseln erfahre, desto mehr bin ich davon überzeugt, dass sie das reinste Wunderland sind!\n\nIldine und ich haben gerade über die Gerüchte gesprochen, dass es in Sturmheim eine Behausung gibt, in der einst eine Vrykulverzauberin namens Tigrid gewohnt hat. Man sagt, das Haus ist wunderbar erhalten und ihre Verzauberungen waren so mächtig, dass sie bis heute anhalten!\n\nDiese Behausung zu untersuchen könnte wertvolles Wissen zutage fördern, {name}.", sourceObjective = "Untersucht Tigrids Behausung in Sturmheim.", completion = "So so, {race}, Ihr habt also mein Zuhause entdeckt... Das ist alles, was von mir übrig ist.\n\nEs reicht nicht einmal aus, um meine geliebten Verzauberungen aufrechtzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39904] = { id = 39904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Die Rache der Verzauberin", description = "Viele Jahrhunderte lang, selbst nach dem Tod, konnte ich lang anhaltende Verzauberungen weben. Aber seitdem mir ein gieriger König meine Verzauberungsrute gestohlen hat, beherrsche ich kaum noch die wenige mir verbliebene Magie.\n\nWenn Ihr dem Geist des Gottkönigs meine Verzauberungsrute abnehmen könnt, werde ich Euch angemessen entlohnen.", sourceObjective = "Bergt Tigrids Verzauberungsrute aus den Hallen der Tapferkeit und kehrt damit zurück zu ihr nach Sturmheim.", progress = "Die Rute ist eine Verlängerung meiner selbst und ich die ihre. Ich möchte sie unbedingt wiederhaben.", completion = "Ihr habt mir zurückgebracht, was mir am wertvollsten ist. Dafür werde ich mein Wissen mit Euch teilen.\n\nWenn Ihr neugierig darauf seid, müsst Ihr mir nur ein paar kleine Zutaten besorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39905] = { id = 39905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da ist was Wahres dran", description = "Ihr wärt uns hier zwar weiterhin eine große Hilfe, aber Euer Meister in Dalaran hat Eure Rückkehr angeordnet.\n\nIch möchte Euch noch einmal für alles danken, was Ihr für uns getan habt. Meine Jäger wissen jetzt, dass sie nicht allein in diesem Krieg kämpfen.", sourceObjective = "Kehrt zu Nalthanis in Dalaran zurück.", completion = "{name}, da seid Ihr ja wieder. Ihr habt ausgezeichnete Arbeit da unten in Azsuna geleistet. Jace hat Euch für die Hilfe mit seinen Truppen und im Kampf gegen die Legion in den höchsten Tönen gelobt.\n\nBevor Ihr geht, möchte ich Euch noch die anderen neuen Formeln für Ringverzauberungen überlassen. Es würde uns in diesem Krieg einen Vorteil verschaffen, wenn Ihr diese mit den anderen Abenteurern teilen könntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[39906] = { id = 39906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung auf den Kampf", description = "{class}, um Euch mein Mal zu verdienen, müsst Ihr Euch zunächst im Kampf beweisen. Es gibt da einen Naga, den ich töten will. Leider aber bin ich dazu nicht stark genug.\n\nBevor wir also zusammen in den Kampf ziehen, benötige ich von Euch Verzauberungen, um stärker zu werden. Ich wette, Ihr habt mittlerweile eine große Anzahl an Verzauberungen im Angebot.\n\nStellt mir davon genug zur Verfügung und macht mich so stark, dass ich in dieser Welt wieder eine bedeutende Rolle spiele.", sourceObjective = "Stellt im Auftrag von Alynglut Pergamente für folgende Gegenstände her: Umhang - Wort der Stärke, Ring - Wort des kritischen Treffers und Ring - Wort der Meisterschaft.", progress = "Sobald ich über die erforderliche Macht verfüge, werden wir beide unsere Kräfte messen.", completion = "<Alynglut nimmt die Pergamente von Euch entgegen und wendet sie auf seine Ausrüstung an.>\n\nJa! Jetzt fühle ich mich, als könnte ich es mit der gesamten Legion aufnehmen!\n\nNun, das ist vielleicht etwas übertrieben, aber ich fühle mich gut auf einen kleinen Kampf vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[39907] = { id = 39907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elfische Verzauberungen", description = "Ihr habt Euch die Male meiner getreuesten Freunde verdient. Außerdem habt Ihr mir meine Liebe zurückgebracht.\n\nIch habe Glück, Euch kennengelernt zu haben, {name}.\n\nJetzt kehrt zu Eurem Meister zurück und berichtet ihm, was Ihr gelernt habt.", sourceObjective = "Kehrt zu Nalthanis in Dalaran zurück.", completion = "<Ihr erzählt Nalthanis von Eurer Zeit bei den verfluchten Elfen und von den Verzauberungen, die Ihr gelernt habt.>\n\nDas ist faszinierend! Ihr habt es mithilfe von Verzauberungen geschafft, eine Beziehung zu den Elfen aufzubauen, und jetzt kommen sie Euch möglicherweise zu Hilfe?\n\nDas sind ein paar mächtige Verzauberungen, die man Euch geschenkt hat, {name}. Lasst sie nicht ungenutzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39910] = { id = 39910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schuld des Druiden", description = "{class}, wenn ich Euch mein Mal gewähren soll, müsst Ihr mich erst so stark machen, dass ich Euch zu Hilfe eilen kann, wenn das nötig sein sollte.\n\nIn den Ruinen von Nar'thalas schlummern meine Götzen. Wie gesagt bin ich nicht stark genug, um sie selbst zu holen.\n\nAber ich spüre, dass Ihr stark genug seid, um diese ehrenlosen Naga zu bekämpfen, die meine Heimat bedrohen.\n\nFindet meine Götzen und bringt sie zu mir zurück. Dann sollt Ihr mein Mal erhalten.", sourceObjective = "Findet Merrus' Götzen der Pranke, Götzen der Klaue und Götzen des Mondes und bringt sie ihm im Zerfallenen Palast zurück.", progress = "Habt Ihr sie gefunden? Sind sie noch heil?", completion = "<Merrus nimmt die Götzen von Euch entgegen und drückt sie fest an seine Brust.>\n\nIhr wisst ja gar nicht, wie lange es her ist, dass ich sie halten durfte. Ich danke Euch, {name}.\n\nIhr habt Euch meinen Respekt verdient und erhaltet deswegen meine Male.", sourceObjectiveStatus = "unverified-source-field" }
quests[39914] = { id = 39914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Dienst der Schildwache", description = "Jetzt, wo ich stärker werde, ist es an der Zeit, Euren und meinen Mut auf die Probe zu stellen. Wie schon erwähnt gibt es da einen mächtigen Naga, den ich töten will.\n\nSein Name ist Tiefenkommandant Eksis. Er hat viele meiner Leute umgebracht, bevor er sich in die Schatten zurückzog, um seine Truppen von dort aus zu befehligen.\n\nIch habe ihn endlich ausfindig gemacht. Er hält sich in einer Höhle östlich von hier auf. Ich möchte, dass wir im Namen meiner Brüder und Schwestern Rache an ihm nehmen.", sourceObjective = "Tötet Tiefenkommandant Eksis und kehrt dann zu Alynglut im Zerfallenen Palast zurück.", completion = "Ihr habt sehr tapfer gekämpft, {name}. Ihr seid wahrlich würdig, meine Male zu tragen. Ich gewähre sie Euch gern.\n\nVielleicht werden wir eines Tages wieder einmal eine Schlacht zusammen schlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39916] = { id = 39916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umschwung des Verrats", description = "Verzauberin Ilanya erinnert sich an mich?\n\n<Der Satyr hält inne und wischt sich eine Träne fort.>\n\nIch habe vor zehntausend Jahren einen großen Fehler begangen. Ich hatte von der Allianz zwischen der Königin und der Legion gehört und meine Überzeugungen verraten, um mich ihnen anzuschließen. Ich wurde in eine Monstrosität verwandelt, nur um im Kampf gegen die Sterblichen umzukommen.\n\nJetzt kehrt die Legion zurück und ich bin lediglich ein nutzloser Geist. Seid mein Gefäß und tötet diese Dämonen dort. Nehmt ihnen die dämonischen Runen ab und zermahlt sie zu Staub.", sourceObjective = "Besiegt die Dämonen am Teufelsfeuervorstoß. Nehmt ihnen die teufelsbesudelten Runen ab und verwandelt sie in 5 Teile Staub der faulen Lügen. Kehrt danach dahin zurück, wo Ihr der gefallenen Priesterin begegnet seid.", progress = "Die Todesschreie der Legion verschaffen mir ein wenig Genugtuung.", completion = "Nachdem ich diesen Dämonen so lange Zeit hilflos zusehen musste, kann ich dank Euch endlich zurückschlagen!\n\nJetzt beginnt die eigentliche Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[39918] = { id = 39918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die abwesende Priesterin", description = "Nach dem Verrat hätte ich niemals gedacht, der Liebe meines Lebens noch einmal gegenübertreten zu können. Aber dank Euch, {name}, kann ich jetzt zurückkehren.\n\nBitte sprecht mit Verzauberin Ilanya. Ich werde sie wissen lassen, dass Ihr meines Mals würdig seid.", sourceObjective = "Kehrt zu Verzauberin Ilanya im Zerfallenen Palast in Azsuna zurück.", completion = "Ich werde Euch auf ewig dankbar sein, dass Ihr mir meine Liebe zurückgebracht habt.\n\nSie ist jetzt bei mir und wird Euch zu Hilfe eilen, wenn Ihr sie ruft. Ich werde Euch Ihre Male gewähren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39920] = { id = 39920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf azurblauen Schwingen", description = "Ich habe ein paar aufregende Neuigkeiten für Euch, {name}. Ildine und ich haben auf einer Exkursion nach Azsuna Kontakt mit den blauen Drachen in der Azurschwingenrast aufgenommen.\n\nEiner der Drachen, Kharmeera, ist ein Verzauberer. Er hätte Interesse daran, mit Euch zusammenzuarbeiten und ein paar unserer Verzauberungen zu optimieren.\n\nIch weiß, dass Ihr gerade erst da unten bei den Elfen wart, aber Kharmeera würde sich ebenfalls freuen, mit Euch zusammenzuarbeiten, wenn Ihr noch mal losziehen möchtet.", sourceObjective = "Sprecht mit dem Drachen Kharmeera in der Azurschwingenrast in Azsuna.", completion = "Ich spüre die Macht Eurer Verzauberungen, {name}. Ja, es wird mir eine Freude sein, mit Euch zusammenzuarbeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[39921] = { id = 39921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Azurblaue Rute", description = "Bevor wir allerdings anfangen können, muss ich Euch um einen kleinen Gefallen bitten. Es ist eine eher peinliche Angelegenheit, aber sie muss erledigt werden, bevor wir zusammenarbeiten können.\n\nAls ich in dieses Land gerufen wurde, hatte ich keine Gelegenheit, meine Sachen zusammenzuraufen. Und das Schlimmste ist, dass ich meinen Zauberstab zurückgelassen habe.\n\nIch glaube aber, es ist viel einfacher, einen neuen herzustellen, als den alten herbeizuschaffen.\n\nHier ist alles, was wir dazu brauchen...", sourceObjective = "Besorgt einen Himmelssteinstab von Dargrul dem Unterkönig in Neltharions Hort, einen strahlenden Zephyrit von Ozruk im Steinernen Kern und einen Haufen uralten Arkhanas aus Scholomance.", progress = "Wie verläuft die Jagd auf die Materialien für den Stab?", completion = "Oh, ja, es scheint alles da zu sein.\n\n<Kharmeera nimmt Euch die Materialien ab und setzt den Stab zusammen.>\n\nUnd jetzt wollen wir mal sehen, was ich Euch zeigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[39923] = { id = 39923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernbohrung", description = "Die Euch bekannten Ringverzauberungen sind gut, aber ich kenne einige noch bessere. Das heißt, ich kenne mächtigere Verzauberungen, die sich für Ringe eignen.\n\nDer Legende nach gibt es vier Konstrukte, deren Kerne mit magischen Verzauberungen verstärkt wurden. Diese Konstrukte patrouillieren jetzt in den Straßen von Suramar.\n\nWenn Ihr ein paar Freunde zusammenrufen und diese Konstrukte besiegen könnt, um ihnen die Kerne zu entnehmen, könnten wir hier mit ihnen arbeiten.", sourceObjective = "Beschafft die Energiekerne von Oldus, Or'ell, Olmoor und Oll'ison. Kehrt zu Kharmeera zurück, wenn Ihr alle vier zusammenhabt.", progress = "Denkt daran, dass Ihr ein paar Freunde brauchen werdet. Diese Konstrukte sind unglaublich mächtig.", completion = "Es ist wahrlich beeindruckend, zu welchen Leistungen Ihr mit Euren jungen Jahren imstande seid.\n\nSollen wir uns jetzt also diesen Kernen widmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39925] = { id = 39925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary Azathar Looted" }
quests[39926] = { id = 39926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Malus Looted" }
quests[39927] = { id = 39927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wingterror Ikzil Looted" }
quests[39928] = { id = 39928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Spirit Honored" }
quests[39929] = { id = 39929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Spirit Honored" }
quests[39930] = { id = 39930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Spirit Honored" }
quests[39931] = { id = 39931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuter hacken", description = "Jetzt, da die Formalitäten erledigt sind, lasst uns dafür sorgen, dass Ihr etwas wirklich Nützliches tut.\n\nAuf den Inseln da unten gibt es eine Unmenge neuer und exotischer Kräuter, mit denen wir erst noch experimentieren müssen.\n\nIch möchte, dass Ihr ein paar dieser Kräuter holt und einige neue Pigmente aus ihnen herstellt. Sobald Ihr genug habt, kommt wieder zu mir zurück, und ich werde es mir ansehen.", sourceObjective = "Beschafft 20 rosenrote Pigmente und 2 fahle Pigmente. Pigmente erhält man durch das Mahlen von Kräutern.", progress = "Nun? Habt Ihr die Pigmente oder vergeudet Ihr nur meine Zeit?", completion = "Ja, mit diesen Pigmenten sollte es funktionieren. Gut gemacht, Schüler.\n\nUnd tatsächlich habe ich eine Glyphe erforscht, die sehr von diesen Pigmenten profitieren würde. Wollt Ihr es mal versuchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39932] = { id = 39932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischtinte", description = "Wisst Ihr, Kräuter sind nicht die einzige Möglichkeit, um Tinte zu bekommen. Man kann auch andere Materialien zu Tinte verarbeiten.\n\nDa fällt mir ein... Ich habe mit dem Gedanken gespielt, meine eigene Version einer Dunkelmond-Karte herzustellen. Wenn diese Jahrmarktsleute das können, kann ich es bestimmt auch.\n\nAber dazu brauchen wir spezielle Reagenzien. Geht hinunter nach Azsuna, holt ein paar Öle und stellt daraus brauchbare Tinte her.", sourceObjective = "Besorgt 5 Teile Mak'ranaöl, 5 Teile Hassnatternöl und 5 Teile Salzaugenöl und mischt sie, um daraus Fischpigmente zu fertigen.", progress = "Mein Pigment?", completion = "Heiliger Strohsack! Das Zeug kann man nicht nur zum Schreiben, sondern auch als Stinkbombe verwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[39933] = { id = 39933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kartenhai", description = "Jetzt haben wir das Pigment, brauchen aber noch eine weitere Zutat.\n\nDie Gäste im Zauberkasten spielen oftmals Kartenspiele und lassen manchmal einige Karten dabei fallen. Seht nach, ob Ihr einige einzelne Karten findet, die Spieler zwischen den Spielen entsorgt haben.", sourceObjective = "Sammelt 10 Hearthstone-Karten im Zauberkasten ein.", progress = "Die Karten sollen hauptsächlich als Referenz dienen...", completion = "Und da haben wir es. Fast so gut wie diese geistlosen Dunkelmond-Dummköpfe.\n\nObwohl dieser Erfolg hauptsächlich meinem Genie zu verdanken ist, denke ich, dass Ihr für Eure Laufarbeit entlohnt werden solltet. Hier ist das Rezept für mein neuestes Meisterwerk.", sourceObjectiveStatus = "unverified-source-field" }
quests[39934] = { id = 39934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere neuen Verbündeten", description = "Seid Ihr schon diesen Dämonenjägern begegnet? Ich bin nicht vollständig von ihrer Bündnistreue überzeugt, aber wenn sie schon mal da sind, können wir auch unseren Vorteil aus ihnen ziehen.\n\nJeder braucht Glyphen, wisst Ihr?\n\nGeht und seht, was Ihr über sie herausfinden könnt. Azsuna wäre ein guter Ort, um damit zu beginnen.\n\nVielleicht hat meine überragende Genialität mittlerweile auf Euch abgefärbt, sodass Ihr mit den neuen Erkenntnissen Eure eigenen Vorlagen ersinnen könnt.", sourceObjective = "Begebt Euch nach Azsuna und sucht dort Allari die Seelenfresserin.", completion = "Seid Ihr zu unserer Verstärkung hier, {class}? Jemanden mit Eurer Stärke können wir immer brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39935] = { id = 39935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis der Macht", description = "Ihr wünscht zu lernen, was es heißt, ein Dämonenjäger zu sein? Das könnte ein Weilchen dauern.\n\nAls Erstes könnt Ihr an unserer Seite kämpfen. Achtet bei unseren Kämpfen gegen die Dämonen einfach darauf, wie wir unsere Kräfte einsetzen.\n\nKehrt zu mir zurück, wenn Ihr damit fertig seid.", sourceObjective = "Tötet 15 Dämonen am Verteidigungsposten der Illidari.", completion = "Einige verurteilen unsere Methoden. Aber wir tun einfach, was getan werden muss, um die Brennende Legion zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39936] = { id = 39936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körperinschriften", description = "Wir Dämonenjäger müssen unsere dunkle Seite in Schach halten, damit wir ihr nicht völlig verfallen und selbst zu Dämonen werden. Deshalb tragen wir diese Markierungen auf unserer Haut.\n\nOben im Norden gibt es einen Dämonenjäger, der Baric Sturmläufer heißt. Er hat vor, seine Markierungen zu verstärken. Geht zu ihm und bringt in Erfahrung, wie wir unsere Dämonen im Zaum halten.", sourceObjective = "Sucht nach Baric Sturmläufer in der Nähe der Leyruinen von Zarkhenar.", completion = "Allari hat Euch geschickt? Ich werde in Kürze mit einem Ritual beginnen und könnte dabei Eure Hilfe brauchen.\n\nIhr scheint ja eher zu den Verbündeten als zu den Feinden zu zählen. In diesen Zeiten sind Verbündete wichtiger als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[39937] = { id = 39937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegensätze stoßen sich ab", description = "Wenn man ein Dämonenjäger wird, muss man ein gewisses Gleichgewicht erhalten, {name}. Um dieses Gleichgewicht zu erhalten, müssen wir uns mit gegensätzlichen Mächten der Natur erfüllen.\n\nTeufelsenergie ist das Gegenstück zu Arkanenergie. Wir zeichnen unsere Körper mit arkanen Runen, um unsere Teufelskräfte im Zaum zu halten.\n\nIhr seid doch <ein Schreiber/eine Schreiberin>, oder? Dann sollte es Euch ja leichtfallen, aus dem Leystaub der Kreaturen in der Ruine da oben geeignete Leypigmente herzustellen.", sourceObjective = "Sammelt 10 Teile Leystaub von den Nachtsüchtigen und den Verdorrten in den Leyruinen von Zarkhenar ein und vermischt sie zu Leypigmenten.", progress = "Obwohl sie Gegensätze sind, kann die eine nicht ohne die andere existieren.", completion = "Ob Ihr es glaubt oder nicht, das war der einfache Teil. Der nächste Teil wird ein wenig schwieriger...\n\n...zumindest für mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[39938] = { id = 39938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herr über den inneren Dämon", description = "Jetzt, da wir alle wichtigen Teile haben, können wir das Ritual beginnen.\n\nIch werde Euch jetzt instruieren, wie Ihr mir helfen könnt. Es ist unerlässlich, dass Ihr meinen Anweisungen folgt, wenn ich sie Euch gebe, oder das Ritual wird scheitern.", sourceObjective = "Helft Baric dabei, sein Ritual zu beenden.", completion = "Es ist vollbracht. Ich fürchte, wenn ich noch länger gewartet hätte, um meine Zauberschutze zu verbessern, hätte der Dämon in mir wahrscheinlich die Oberhand gewonnen.\n\nNochmals vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39939] = { id = 39939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreiberwissen", description = "Wir bekämpfen nicht einfach nur die Dämonen, {name}. Wir beobachten sie.\n\nEine meine besten Dämonenjägerinnen, Zaria Schattenherz, sammelt gerade Informationen über die Dämonen im Teufelsfeuervorstoß.\n\nGeht zu ihr. Sie wird Euch das beibringen, was sie seit dem Eindringen der Dämonen in diese Region erfahren hat.", sourceObjective = "Sucht nach Zaria Schattenherz in der Nähe des Teufelsfeuervorstoßes in Azsuna.", completion = "Allari hat Euch geschickt, damit Ihr von mir lernt? Dann habe ich Euch viel zu erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39940] = { id = 39940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runen der Kraft", description = "Schaut gut zu und lernt, <Schreiber/Schreiberin>. Wenn sich die Dämonen in einem Gebiet ausbreiten, platzieren die klügeren von ihnen Runen auf dem Boden. Die teuflische Verderbnis befällt die ganze Berggegend hier, aber im Bereich der Runen wirkt sie am stärksten. Dort verhindert sie, dass jemals wieder etwas Reines wachsen kann.\n\nStudiert diese Runen.", sourceObjective = "Studiert 8 Teufelskraftrunen.", completion = "Ihr habt sicher bemerkt, dass diesen Runen große Energie innewohnt.\n\nJe mehr wir über die Legion wissen, desto besser können wir sie bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39941] = { id = 39941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle ist der Schlüssel", description = "Wir Dämonenjäger entfernen unsere Augen in einem Ritual, um die Dämonen deutlicher sehen zu können.\n\nDort unten wandelt ein Dämonenkommandant unter seinen Truppen, der mit normalen Augen nicht zu sehen ist. Er kontrolliert das Chaos, so wie wir unser Chaos im Zaum halten müssen.\n\nZerstört seinen Schutzkristall und tötet ihn dann.", sourceObjective = "Zerstört den Kristall, der dem Aufseher Felorax Schutz gewährt, und tötet ihn dann.", completion = "Ich muss Euch loben, Schreiber. Ihr gebt einen ausgezeichneten Dämonenjäger ab.\n\nNehmt diese Tinte als Lohn für Eure Mühen. Ich habe keine Verwendung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[39942] = { id = 39942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aethremkristall", description = "<Das meiste Aethril weist eine klar umrissene, kristalline Faser in der Mitte der Blüte auf, aber diese hier ist besonders schön ausgeprägt.>\n\n<Professor Pallin hätte sicherlich Interesse daran.>", sourceObjective = "Bringt den Aethremkristall zu Professor Pallin in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Ein Kristall... inmitten der Blüte? Das bringt mich auf eine Idee.\n\nAls ich jünger war, habe ich mich an der Juwelierskunst versucht. Schaut Euch mal diese Technik an...", sourceObjectiveStatus = "unverified-source-field" }
quests[39943] = { id = 39943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bürden der Jagd", description = "Ich kann Euch nichts weiter lehren, <Schreiber/Schreiberin>. Die Illidari stehen im Kampf gegen die Legion hinter Euch.", sourceObjective = "Meldet Euch bei Professor Pallin.", completion = "<Professor Pallin sieht sich Eure Dämonenjägerglyphen an.>\n\nSieh an! Ihr könnt wohl besser selbstständig arbeiten, als ich gedacht hatte.\n\nSeht Euch diese Glyphe an, die Ihr hier gesetzt habt. Wenn Ihr dieses Symbol herumdreht und hier die Breite des Pinselstrichs anpasst...", sourceObjectiveStatus = "unverified-source-field" }
quests[39944] = { id = 39944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöse Botschaften", description = "Die Frau vom Archäologieladen hat uns gerade ein paar Tafeln überlassen, die wir entziffern sollen. Dass sie in antikem Vrykul geschrieben sind, könnte jeder Trottel feststellen. Aber ich habe meinen Kodex einem meiner Schüler geliehen und deswegen kann ich sie hier vor Ort nicht entschlüsseln.\n\nSein Name ist Nicholo Schnellzünder und er befindet sich in Sturmheim. Sagt ihm, dass er seine Ausbildung als gescheitert betrachten darf, wenn er diese Tafeln nicht entschlüsseln kann.\n\nMehr gibt es dazu nicht zu sagen.", sourceObjective = "Bringt die Tafeln zu Nicholo Schnellzünder in Sturmheim.", completion = "Im Ernst? Was will Pallin von mir?!\n\nDieser alte Angeber hält sich für so großartig, dabei mache immer ich die ganze Arbeit. Eigentlich müsste ich für den ganzen Laden verantwortlich sein.\n\nAber gut, ich helfe Euch. Wenn Ihr mir auch helft...", sourceObjectiveStatus = "unverified-source-field" }
quests[39945] = { id = 39945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runen in den Ruinen", description = "Leider ist Pallins Kodex nicht vollständig. Es gibt hier so viele Symbole, die mit dem, was wir gelernt haben, einfach nicht zu entziffern sind.\n\nEs scheint, als müssten wir noch mehr Schrifttafeln in dem Gebiet sammeln, das die Vrykul Haustvald nennen.", sourceObjective = "Sammelt 10 uralte Runentafeln der Vrykul in Haustvald ein.", progress = "Wir brauchen diese Schrifttafeln, wenn wir beim Entschlüsseln ihrer Sprache weiterkommen wollen.", completion = "Ich glaube, sie enthalten genug Informationen, um den Kodex fertigzustellen. Ausgezeichnete Arbeit, {name}.\n\nWenn ich das sagen darf, es ist schön, endlich nicht mehr derjenige zu sein, der die ganze Laufarbeit machen muss.", sourceObjectiveStatus = "unverified-source-field" }
